  try{out.innerHTML=(ST.demo?'<div class="demo-banner">Está viendo <strong>datos ficticios</strong> generados para probar la herramienta. Ninguna cifra corresponde a pacientes reales. Clave de la conciliación (Producción asistencial): <span class="mono">demo1234</span></div>':"")+(rutaBanner(ST.view))+({turno:vTurno,pac:vPac,val:vVal,lab:vLab,vac:vVac,tx:vTx,acc:vAcc,sem:vSem,ind:vInd,seg:vSeg,far:vFarm,alert:vAlert,rep:vRep,fin:vFin,cal:vCal,ref:vRef,doc:()=>typeof pxDocsFor==="function"?pxDocsFor("hd"):'<div class="panel empty">Los documentos se consultan desde el sistema de gestión.</div>'})[ST.view]();}
  catch(e){console.error(e);out.innerHTML='<div class="alert bad"><p>Error al dibujar esta pestaña: '+esc(e.message)+'</p></div>';}
