function vStart(){return head("Cómo empezar","El libro de hemodiálisis guarda pacientes, sesiones, eventos, paraclínicos y novedades. Se carga al empezar la jornada y se descarga al terminar.")+
 '<div class="start">'+
 '<div class="panel"><h3>Ya tengo el libro</h3><p class="note">Cargue el archivo «Hemodialisis_libro_…xlsx» que descargó la última vez.</p><label class="btn primary" for="bookfile" style="justify-self:start">Cargar libro</label></div>'+
 '<div class="panel"><h3>Vengo del Dashboard mensual</h3><p class="note">Cargue el «Dashboard MES.xlsx». Se importan maestro, turnos, asistencias del mes, laboratorios, vacunación, complicaciones, novedades y tarifas. Lo que no cuadre queda en Calidad del dato.</p><label class="btn" for="bookfile" style="justify-self:start">Importar Dashboard</label></div>'+
 '<div class="panel"><h3>Solo quiero mirar</h3><p class="note">38 pacientes inventados con seis meses de sesiones, laboratorios y eventos.</p><button type="button" class="btn" data-a="demo" style="justify-self:start">Ver con datos ficticios</button></div>'+
 '</div>'+
 '<div class="panel"><h3>Qué hace cada pestaña</h3><div class="lists"><ul><li><strong>Turno del día</strong>: cada sesión con un clic; UF neta y tasa de UF de la sesión; GID, TA, glucometría y Kt/V de las últimas 8 sesiones a la vista; sesiones extra y cambio de silla.</li><li><strong>Pacientes</strong>: maestro, datos CAC, movimientos, atenciones, estudios e imágenes con lo que hay que tener presente.</li><li><strong>Valoración mensual</strong>: lista de chequeo, interpretación contra la meta de cada paciente y texto para la HC.</li><li><strong>Paraclínicos</strong>: carga por fecha con Kt/V calculado, solicitud del mes siguiente (la misma que ve Laboratorio) y tendencias.</li></ul><ul><li><strong>Vacunación VHB</strong>: dosis aplicadas, próxima dosis y estado según HBsAg, anti-HBc y anti-HBs.</li><li><strong>Acceso vascular</strong>: catéteres, meses con catéter, ruta a FAV y novedades.</li><li><strong>Trasplante</strong>: estado del proceso y estudios que faltan.</li><li><strong>Calidad de diálisis y riesgo</strong>: matriz de evaluación integral y semáforo.</li></ul><ul><li><strong>Indicadores CAC</strong>: fichas CAC 2026 de HD e institucionales, con metas.</li><li><strong>Alertas</strong>: lo que hay que hacer hoy.</li><li><strong>Reportes</strong>: matrices CAC por EPS y Excel de la cohorte.</li><li><strong>Calidad del dato</strong>, <strong>Documentos y guías</strong> (con la ruta del paciente) y <strong>Referencia</strong>. Seguridad del paciente, IAAS, PROA, Laboratorio y Producción asistencial se trabajan en sus módulos del sistema.</li></ul></div></div>';}

