  const all=k=>ST.book[k].filter(o=>o.Paciente===p.ID);
  const S=all("ses").sort((a,b)=>b.Fecha-a.Fecha);
  h+='<details class="hist" open><summary>Sesiones ('+S.length+')</summary>'+tb("ses",[["Fecha",r=>fd(r.Fecha)],["Estado",r=>esc(r.Estado)+(r.Responsable?'<span class="sub">'+esc(r.Responsable)+(r.Motivo?" · "+esc(r.Motivo):"")+'</span>':"")],["Min",r=>esc(r.DuracionMin??"")],["Acceso",r=>esc(r.Acceso||"")],["Peso",r=>(r.PesoPre??"")+(r.PesoPost!=null?" → "+r.PesoPost:"")],["TAS",r=>esc(r.TASPre??"")],["Registró",r=>'<span class="sub">'+esc(r.Usuario||"")+'</span>']],S.slice(0,40),true)+(S.length>40?'<p class="note">Se muestran las 40 más recientes.</p>':"")+'</details>';
  h+='<details class="hist"><summary>Eventos ('+all("evt").length+')</summary>'+tb("evt",[["Fecha",r=>fd(r.Fecha)],["Evento",r=>esc(r.Tipo)],["Severidad",r=>esc(r.Severidad||"")],["Conducta",r=>esc(r.Conducta||"")],["Resuelto",r=>esc(r.Resuelto||"")+(r.Resuelto!=="Sí"&&live(r)?' <button type="button" class="lnk" data-a="evclose|'+r.ID+'">cerrar</button>':"")],["Hemocultivo",r=>esc(r.Hemocultivo||"")]],all("evt").sort((a,b)=>b.Fecha-a.Fecha),true)+'</details>';
  const Lb=all("lab").sort((a,b)=>b.FechaToma-a.FechaToma);
