  h+='<details class="hist"><summary>Novedades ('+all("nov").length+')</summary>'+tb("nov",[["Tipo",r=>esc(r.Tipo)+(r.Causa?'<span class="sub">'+esc(r.Causa)+(r.Atribuible?" · atribuible: "+esc(r.Atribuible):"")+'</span>':"")],["Inicio",r=>fd(r.Inicio)],["Fin",r=>r.Fin?fd(r.Fin):(live(r)?'<button type="button" class="lnk" data-a="novclose|'+r.ID+'">registrar egreso</button>':"")],["Descripción",r=>esc(r.Descripcion||"")]],all("nov").sort((a,b)=>b.Inicio-a.Inicio),true)+'</details>';
  h+='<details class="hist"><summary>Movimientos ('+all("mov").length+')</summary>'+tb("mov",[["Fecha",r=>fd(r.Fecha)],["Tipo",r=>esc(r.Tipo)],["Detalle",r=>esc(r.Detalle||"")],["Registró",r=>'<span class="sub">'+esc(r.Usuario||"")+'</span>']],all("mov").sort((a,b)=>b.Fecha-a.Fecha),true)+'</details>';
  h+='<details class="hist"><summary>Novedades de acceso ('+all("acn").length+')</summary>'+tb("acn",[["Fecha",r=>fd(r.Fecha)],["Novedad",r=>esc(r.Tipo)],["Acceso resultante",r=>esc(r.AccesoResultante||"")],["Detalle",r=>esc(r.Detalle||"")]],all("acn").sort((a,b)=>b.Fecha-a.Fecha),true)+'</details>';
  h+='<details class="hist"><summary>Atenciones por disciplina ('+all("ate").length+')</summary>'+tb("ate",[["Fecha",r=>fd(r.Fecha)],["Disciplina",r=>esc(r.Disciplina)],["Nota",r=>esc(r.Nota||"")],["Registró",r=>'<span class="sub">'+esc(r.Usuario||"")+'</span>']],all("ate").sort((a,b)=>b.Fecha-a.Fecha),true)+'</details>';
  h+='<details class="hist"><summary>Valoraciones mensuales ('+all("val").length+')</summary>'+tb("val",[["Fecha",r=>fd(r.Fecha)],["Profesional",r=>esc(r.Profesional||"")],["Calidad",r=>esc(r.CalidadCategoria||"")],["Plan",r=>'<span style="font-size:13px">'+esc(String(r.Plan||"").slice(0,160))+'</span>']],all("val").sort((a,b)=>b.Fecha-a.Fecha),true)+'</details>';
  h+='<details class="hist"'+(all("est").length?" open":"")+'><summary>Estudios, imágenes y procedimientos ('+all("est").length+')</summary>'+tb("est",[["Fecha",r=>fd(r.Fecha)],["Estudio",r=>esc(r.Nombre)+'<span class="sub">'+esc(r.Tipo||"")+(r.Relevante==="Sí"?" · tener presente":"")+'</span>'],["Qué dice",r=>'<span style="font-size:13px">'+esc(r.Resultado||"")+'</span>'+(r.Seguimiento?'<span class="sub">Seguimiento: '+esc(r.Seguimiento)+'</span>':"")],["Próximo control",r=>r.ProximoControl?fd(r.ProximoControl):""],["Soporte",r=>'<span class="sub">'+esc(r.Soporte||"")+'</span>']],all("est").sort((a,b)=>b.Fecha-a.Fecha),true)+'</details>';
  const vs=vacStatus(p,ST.corte);h+='<details class="hist"><summary>Vacunación VHB ('+all("vac").length+' dosis) · '+esc(vacEtiqueta(vs.code))+'</summary><p class="note">'+esc(vs.txt)+'</p>'+tb("vac",[["Fecha",r=>fd(r.Fecha)],["Serie",r=>esc(r.Serie||"1")],["Dosis",r=>esc(r.NumDosis??"")],["Esquema",r=>'<span style="font-size:13px">'+esc(r.Esquema||"")+'</span>'],["Lote",r=>esc(r.Lote||"")],["Registró",r=>'<span class="sub">'+esc(r.Usuario||"")+'</span>']],all("vac").sort((a,b)=>b.Fecha-a.Fecha),true)+'</details>';
  const ts=txState(p);h+='<details class="hist"><summary>Trasplante · '+esc(p.TxEstado||"Sin evaluar")+' · '+ts.hecho+'/'+ts.apl+' estudios</summary>'+(ts.falta.length?'<p class="note">Faltan: '+esc(ts.falta.map(x=>x.it.split(" · ").pop()).join("; "))+'</p>':'<p class="note">Lista de estudios completa.</p>')+'<button type="button" class="btn sm" data-a="go2tx|'+p.ID+'">Gestionar en Trasplante</button></details>';
  h+='<details class="hist"><summary>Contactos ('+all("ctc").length+')</summary>'+tb("ctc",[["Fecha",r=>fd(r.Fecha)],["Medio",r=>esc(r.Medio)],["Resultado",r=>esc(r.Resultado||"")],["Nota",r=>esc(r.Nota||"")],["Registró",r=>'<span class="sub">'+esc(r.Usuario||"")+'</span>']],all("ctc").sort((a,b)=>b.Fecha-a.Fecha),false)+'</details>';
