  ["PTH","Alb","Ferritina","TSAT","HbA1c","FA","LDL"].forEach(k=>{if(lab[k].v==null){const a=lastLab(p,k,addMonths(d,-6),d);if(a){const all=(p._lab[k]||[]).filter(l=>l.FechaToma<a.FechaToma);const b=all.pop();lab[k]={a,b,v:num(a.Valor),pv:b?num(b.Valor):null,t:a.Valor,old:true};}}});
