  const meds=p._med.filter(x=>!x.Fin||x.Fin>=ms);const AEE_ON=["Mantener","Iniciar","Aumentar","Disminuir"];const aee=meds.some(x=>AEE.includes(x.Medicamento))||AEE_ON.includes(D.f.aee)||(()=>{const pv=p._val.filter(v=>v.Mes<D.mes).pop();if(!pv)return false;try{return AEE_ON.includes((JSON.parse(pv.Datos||"{}").f||{}).aee);}catch(e){return false;}})();const disp=p._dis.filter(x=>x.Mes===D.mes);
  const cal=calidadScore(calidadAuto(p,d),{sint_frec:D.f.cal_sint_frec,cong:D.f.cal_cong,acc:D.f.cal_acc,rec:D.f.cal_rec,fat:D.f.cal_fat});
