  if(X.g.n)ea+="Ganancia interdialítica promedio "+f1(X.g.kg)+" kg ("+f1(X.g.pct)+" % del peso seco) en "+X.g.n+" intervalos; UF promedio "+f1(X.g.uf)+" kg"+(X.g.ufrMax!=null?", UFR máxima "+f1(X.g.ufrMax)+" mL/kg/h":"")+". ";
  if(X.ta.n)ea+="TA pre-diálisis promedio "+fmtTA(X.ta.sPre,X.ta.dPre)+" mmHg"+(X.ta.sPost!=null?", post "+fmtTA(X.ta.sPost,X.ta.dPost):"")+(X.ta.min!=null?", PAS mínima "+Math.round(X.ta.min):"")+". ";
  if(X.gl&&X.gl.n)ea+="Glucometrías: promedio "+fc(X.gl.avg)+" mg/dL, "+X.gl.meta+" de "+X.gl.n+" en rango"+(X.gl.hipo?", "+X.gl.hipo+" hipoglucemias":"")+". ";
