  if(X.hosp.length)ea+="Hospitalización: "+X.hosp.map(n=>fd(n.Inicio)+(n.Fin?" a "+fd(n.Fin):" (sin egreso)")+" por "+(n.Causa||n.Descripcion||"causa no registrada").toLowerCase()).join("; ")+". ";
  const sint=(f.sint||[]).filter(x=>x!=="Asintomático");ea+=sint.length?"Refiere "+sint.join(", ").toLowerCase()+". ":(f.sint||[]).includes("Asintomático")?"Asintomático. ":"";
  if(f.otros)ea+=f.otros.trim().replace(/\.?$/,". ");if(f.diuresis!==undefined&&f.diuresis!=="")ea+="Diuresis residual "+f.diuresis+" mL/24 h. ";
