  const grp=[["Adecuación dialítica",["KtV","UFR"]],["Volumen y presión arterial",["GID","TA"]],["Anemia",["Hb","TSAT","Ferritina"]],["Metabolismo mineral y óseo",["Ca","P","PTH"]],["Potasio",["K"]],["Nutrición",["Alb"]],["Diabetes",["HbA1c","Glucometría"]]];
