  const txs=txState(p);an+="- Trasplante: "+(p.TxEstado||"sin evaluar").toLowerCase()+(TX_EN_PROCESO.includes(p.TxEstado)?"; estudios "+txs.hecho+" de "+txs.apl+(txs.falta.length?", faltan "+txs.falta.slice(0,5).map(x=>x.it.split(" · ").pop().toLowerCase()).join(", ")+(txs.falta.length>5?" y otros":""):""):"")+".\n";
