  const pl=[];const presc=[f.horas?f.horas+" horas":"",f.qb?"Qb "+f.qb:"",f.qd?"Qd "+f.qd:"",f.dializador?"dializador "+f.dializador:"",f.bk?"baño K "+f.bk:"",f.bca?"baño Ca "+f.bca:"",f.hep?f.hep:""].filter(Boolean);
