  [["aee","AEE"],["hierro","Hierro IV"],["quel","Quelante de fósforo"],["vitd","Vitamina D activa"],["calcim","Calcimimético"],["antihta","Antihipertensivos"],["insulina","Insulina o hipoglucemiantes"]].forEach(([k,l])=>{if(f[k]&&f[k]!=="No aplica")pl.push(l+": "+f[k].toLowerCase()+(f[k+"_d"]?" ("+f[k+"_d"]+")":"")+".");});
