  const nm=addMonths(X.ms,1);const nx=solExamsFor(p,ym(nm)).map(k=>(EX[k]||{l:k}).l);if(nx.length)pl.push("Paraclínicos del próximo mes: "+nx.join(", ")+".");
  if(f.planOtro)pl.push(f.planOtro.trim().replace(/\.?$/,"."));if(f.proxCtrl)pl.push("Próximo control: "+fd(pdate(f.proxCtrl))+".");
