/* ================= paraclínicos ================= */
const LAB_GRID_DEF=["Hb","BUNpre","BUNpost","K","Ca","P","Alb","PTH"];
function vLab(){ensureIdx();const sub=ST.ui.lsub||"carga";
  let h=head("Paraclínicos","Carga por fecha de toma (con cálculo automático del Kt/V a partir del BUN pre y post), tendencia de cada paciente y vencidos según el calendario institucional.",'')+'<div class="seg" role="group">'+[["carga","Carga por fecha de toma"],["sol","Solicitud del próximo mes"],["trend","Tendencia por paciente"],["cal","Vencidos y calendario"]].map(([k,l])=>'<button type="button" data-a="lsub|'+k+'" aria-pressed="'+(sub===k)+'">'+l+'</button>').join("")+'</div>';
  return h+(sub==="carga"?labCarga():sub==="sol"?solView("hd"):sub==="trend"?labTrend():labCal());}
function sesFor(p,d){let s=p._ses.find(x=>iso(x.Fecha)===iso(d)&&x.Estado==="Realizada");if(s)return{s,exact:true};for(let i=p._ses.length-1;i>=0;i--){const x=p._ses[i];if(x.Fecha<d&&x.Estado==="Realizada"&&dayDiff(x.Fecha,d)<=3)return{s:x,exact:false};}return null;}
function ktvCalc(p,d,pre,post){const r=sesFor(p,d);const t=r&&num(r.s.DuracionMin)?num(r.s.DuracionMin):(num(p.DuracionMin)||240);const w=r&&num(r.s.PesoPost)?num(r.s.PesoPost):(num(p.PesoSeco)||null);const uf=r&&num(r.s.PesoPre)!=null&&num(r.s.PesoPost)!=null?num(r.s.PesoPre)-num(r.s.PesoPost):0;
  const k=ktvDaugirdas(pre,post,t,uf,w);return{k,urr:pre&&post?(1-post/pre)*100:null,t,w,uf,src:r?(r.exact?"sesión del día":"sesión del "+fd(r.s.Fecha)):"sin sesión: tiempo prescrito, UF 0",ok:k!=null};}
function labCarga(o){o=o||{};const c=ST.corte;const d=ST.ui.ldate||iso(c);const ex=o.ex||ST.ui.lex||LAB_GRID_DEF;const dd=pdate(d)||c;
  const L=ST.book.pac.filter(p=>epsOk(p)&&(activeAt(p,dd)||(o.pids&&o.pids.has(p.ID)))&&(!o.pids||o.pids.has(p.ID))).sort((a,b)=>String(a.ID).localeCompare(String(b.ID)));const hasBun=ex.includes("BUNpre")&&ex.includes("BUNpost");
  let h='<div class="panel" style="display:grid;gap:10px"><div class="copyrow"><label class="f" style="max-width:180px">Fecha de toma<input type="date" id="ldate" value="'+d+'"></label><button type="button" class="btn primary" data-a="lsave">Guardar paraclínicos</button></div>'+
   (o.ex?'':'<div class="copyrow" role="group" aria-label="Exámenes visibles">'+EXAMS.filter(e=>!["EscalaCV","KtV","URR"].includes(e.k)).map(e=>'<label class="chk" style="font-size:13px;display:inline-flex;gap:4px;align-items:center"><input type="checkbox" data-a="lex|'+e.k+'"'+(ex.includes(e.k)?" checked":"")+'>'+esc(e.k)+'</label>').join(" ")+'</div>')+
   '<p class="note">Solo se guardan las celdas con valor; el número gris es el último resultado. Con BUN pre y post la herramienta calcula spKt/V por Daugirdas II (−ln(R − 0,008·t) + (4 − 3,5·R)·UF/peso) con el tiempo, la UF y el peso post de la sesión de ese día, y el PRU. Valores fuera del rango plausible no se guardan.</p>'+
   '<div class="tablebox labgrid"><table><thead><tr><th>Paciente</th>'+ex.map(k=>'<th>'+esc(EX[k].l)+(EX[k].u?'<span class="sub" style="text-transform:none">'+EX[k].u+'</span>':"")+'</th>').join("")+(hasBun?'<th>Kt/V calculado</th>':"")+'</tr></thead><tbody>'+
   L.map(p=>'<tr data-lp="'+p.ID+'"><td><strong>'+esc(p.ID)+'</strong><span class="sub">'+esc(nombre(p))+'</span></td>'+ex.map(k=>{const e=EX[k];if(e.dm&&p.DM!=="SI")return'<td class="sd">no aplica</td>';const l=lastLab(p,k,null,addDays(c,365));const ph=l?String(l.Valor):"";const nm='lv|'+p.ID+'|'+k;
     return'<td>'+(e.txt?'<select data-l="'+nm+'">'+opt(e.txt,"","—")+'</select>':'<input type="text" inputmode="decimal" data-l="'+nm+'" placeholder="'+esc(ph)+'">')+(l?'<span class="sub">'+fd(l.FechaToma)+'</span>':"")+'</td>';}).join("")+(hasBun?'<td class="mono" data-kv="'+p.ID+'"><span class="sd">—</span></td>':"")+'</tr>').join("")+'</tbody></table></div></div>';
  return h;}
function labPreview(pid){const cell=document.querySelector('[data-kv="'+pid+'"]');if(!cell)return;const g=k=>{const el=document.querySelector('[data-l="lv|'+pid+'|'+k+'"]');return el?num(el.value):null;};const a=g("BUNpre"),b=g("BUNpost");if(a==null||b==null){cell.innerHTML='<span class="sd">—</span>';return;}
  const r=ktvCalc(IDX.pac.get(pid),pdate($("ldate").value)||ST.corte,a,b);cell.innerHTML=r.ok?'<strong>'+f1(r.k,2)+'</strong><span class="sub">PRU '+f1(r.urr,0)+' % · '+esc(r.src)+'</span>':'<span style="color:var(--bad)">No calculable</span><span class="sub">BUN post debe ser menor que el pre</span>';}
function labSave(){if(needUser())return;const d=pdate($("ldate").value);if(!d){toast("Fecha de toma inválida.");return;}if(d>TODAY()){toast("La fecha de toma no puede ser futura.");return;}
  const errs=[],ok=[];const bun={};
  document.querySelectorAll("[data-l]").forEach(el=>{const v=el.value.trim();if(!v)return;const[,pid,k]=el.dataset.l.split("|");const e=EX[k];if(!e.txt){const n=num(v);if(n==null||n<e.lo||n>e.hi){errs.push(pid+" "+k+"="+v);el.style.borderColor="var(--bad)";return;}ok.push({Paciente:pid,FechaToma:d,Examen:k,Valor:n,Metodo:""});if(k==="BUNpre"||k==="BUNpost"){(bun[pid]=bun[pid]||{})[k]=n;}}else ok.push({Paciente:pid,FechaToma:d,Examen:k,Valor:v,Metodo:""});});
  Object.entries(bun).forEach(([pid,b])=>{if(b.BUNpre==null||b.BUNpost==null)return;const r=ktvCalc(IDX.pac.get(pid),d,b.BUNpre,b.BUNpost);if(!r.ok){errs.push(pid+": BUN post no menor que el pre");return;}
    const met="Daugirdas II calculado · BUN "+b.BUNpre+"/"+b.BUNpost+" · t "+r.t+" min · UF "+f1(r.uf,1)+" kg · peso "+(r.w??"?")+" kg · "+r.src;ok.push({Paciente:pid,FechaToma:d,Examen:"KtV",Valor:Math.round(r.k*100)/100,Metodo:met});ok.push({Paciente:pid,FechaToma:d,Examen:"URR",Valor:Math.round(r.urr*10)/10,Metodo:"Calculado de BUN pre y post"});});
  if(errs.length){toast("Revise: "+errs.slice(0,4).join(", ")+(errs.length>4?" …":"")+". No se guardó nada.");return;}
  if(!ok.length){toast("No hay valores para guardar.");return;}
  ok.forEach(o=>addRec("lab","L-",o));reindex();[...new Set(ok.filter(o=>["AntiHBs","HBsAg","AntiHBc"].includes(o.Examen)).map(o=>o.Paciente))].forEach(id=>vacSync(IDX.pac.get(id)));reindex();toast(ok.length+" resultados guardados con fecha "+fd(d)+(Object.keys(bun).length?", con Kt/V calculado":"")+".");render();}
function labCal(){const c=ST.corte;const f=ST.ui.lcf||"venc";
  const L=ST.book.pac.filter(p=>epsOk(p)&&activeAt(p,c)).map(p=>({p,due:labDue(p,c)}));
  const cnt={vencido:0,"este mes":0,"próximo mes":0};L.forEach(x=>x.due.forEach(d=>{if(cnt[d.st]!=null)cnt[d.st]++;}));
  let h='<div class="tiles"><div class="tile bad"><span class="tv">'+cnt.vencido+'</span><span class="tl">exámenes vencidos (no tomados en el último mes programado)</span></div><div class="tile warn"><span class="tv">'+cnt["este mes"]+'</span><span class="tl">tocan este mes y aún no tienen resultado</span></div><div class="tile"><span class="tv">'+cnt["próximo mes"]+'</span><span class="tl">tocan el próximo mes</span></div></div>';
  h+='<div class="seg" role="group">'+[["venc","Vencidos y de este mes"],["prox","Próximo mes"],["all","Todo"]].map(([k,l])=>'<button type="button" data-a="lcf|'+k+'" aria-pressed="'+(f===k)+'">'+l+'</button>').join("")+'</div><p class="note">La solicitud del mes siguiente, con exportación y corrección, está en «Solicitud del próximo mes» y en el módulo Laboratorio.</p>';
  const keep=d=>f==="all"?d.st!=="al día":(f==="venc"?(d.st==="vencido"||d.st==="este mes"):d.st==="próximo mes");
  const rows=L.map(x=>({p:x.p,d:x.due.filter(keep)})).filter(x=>x.d.length);
  h+='<div class="panel tablebox" style="padding:0"><table><thead><tr><th>Paciente</th><th>Exámenes</th></tr></thead><tbody>'+(rows.map(x=>'<tr><td><strong>'+esc(x.p.ID)+'</strong><span class="sub">'+esc(nombre(x.p))+' · '+esc(x.p.Turno||"")+'</span></td><td><div class="copyrow" style="gap:5px">'+x.d.map(d=>'<span class="st '+(d.st==="vencido"?"bad":d.st==="este mes"?"warn":"base")+'" title="'+esc(FREQ_TXT[d.f]||"")+' · último: '+(d.last?fd(d.last.FechaToma):"nunca")+'">'+esc(EX[d.k].l)+(d.last?' · '+fd(d.last.FechaToma):' · sin registro')+'</span>').join("")+'</div></td></tr>').join("")||'<tr><td colspan="2" class="empty">Nada pendiente con este filtro.</td></tr>')+'</tbody></table></div>';
  return h;}
/* gráfico de línea pequeño con banda de meta */
function lineChart(pts,o){o=o||{};const W=360,H=150,L=40,R=10,T=14,B=26;const p2=(o.pts2||[]).filter(p=>p.v!=null&&p.d);const v=pts.map(p=>p.v).filter(x=>x!=null).concat(p2.map(p=>p.v));if(!pts.length&&!p2.length||!v.length)return'<p class="note">Sin datos.</p>';
  let lo=Math.min(...v,o.band?o.band[0]:Infinity),hi=Math.max(...v,o.band?o.band[1]:-Infinity);if(o.ref!=null){lo=Math.min(lo,o.ref);hi=Math.max(hi,o.ref);}const pad=(hi-lo)*0.15||1;lo-=pad;hi+=pad;
  const ts=pts.concat(p2).map(p=>p.d.getTime());const t0=Math.min(...ts),t1=Math.max(...ts);const X=d=>L+(t1===t0?0.5:(d.getTime()-t0)/(t1-t0))*(W-L-R),Y=y=>T+(1-(y-lo)/(hi-lo))*(H-T-B);
  let s='<svg class="chart" viewBox="0 0 '+W+' '+H+'" role="img" aria-label="'+esc(o.t||"tendencia")+'">';
  if(o.band){const a=Y(Math.min(o.band[1],hi)),b=Y(Math.max(o.band[0],lo));s+='<rect x="'+L+'" y="'+a+'" width="'+(W-L-R)+'" height="'+Math.max(0,b-a)+'" fill="var(--ok-soft)"/>';}
  if(o.ref!=null)s+='<line x1="'+L+'" x2="'+(W-R)+'" y1="'+Y(o.ref)+'" y2="'+Y(o.ref)+'" stroke="var(--ok)" stroke-dasharray="4 4"/>';
  [lo+pad,(lo+hi)/2,hi-pad].forEach(t=>{s+='<text class="ax" x="'+(L-5)+'" y="'+(Y(t)+4)+'" text-anchor="end">'+f1(t,o.dec??1)+'</text>';});
  const P=pts.filter(p=>p.v!=null);if(P.length>1)s+='<polyline fill="none" stroke="var(--accent)" stroke-width="2" points="'+P.map(p=>X(p.d)+","+Y(p.v)).join(" ")+'"/>';
  if(p2.length>1)s+='<polyline fill="none" stroke="var(--warn)" stroke-width="1.4" points="'+p2.map(p=>X(p.d)+","+Y(p.v)).join(" ")+'"/>';
  P.forEach((p,i)=>{s+='<circle cx="'+X(p.d)+'" cy="'+Y(p.v)+'" r="'+(i===P.length-1?3.6:2.4)+'" fill="var(--accent)"><title>'+fd(p.d)+': '+f1(p.v,o.dec??1)+'</title></circle>';});
  const lp=P[P.length-1];if(lp)s+='<text class="val" x="'+Math.min(W-R,X(lp.d))+'" y="'+(Y(lp.v)-7)+'" text-anchor="end">'+f1(lp.v,o.dec??1)+'</text>';
  s+='<text class="ax" x="'+L+'" y="'+(H-8)+'">'+fd(new Date(t0))+'</text><text class="ax" x="'+(W-R)+'" y="'+(H-8)+'" text-anchor="end">'+fd(new Date(t1))+'</text>';return s+'</svg>';}
function labTrend(){const act=ST.book.pac.filter(p=>epsOk(p)&&activeAt(p,ST.corte)).sort((a,b)=>String(a.ID).localeCompare(b.ID));const pid=ST.ui.tpid&&IDX.pac.get(ST.ui.tpid)?ST.ui.tpid:(act[0]&&act[0].ID);if(!pid)return'<div class="panel empty">Sin pacientes activos.</div>';
  ST.ui.tpid=pid;const p=IDX.pac.get(pid);const m=metasDe(p);const a=addMonths(ST.corte,-12);const ser=k=>(p._lab[k]||[]).filter(l=>l.FechaToma>a&&num(l.Valor)!=null).map(l=>({d:l.FechaToma,v:num(l.Valor)}));
  const R=p._ses.filter(s=>s.Fecha>addMonths(ST.corte,-3)&&s.Estado==="Realizada");const gid=gidStats(p,ST.corte,40).list.reverse().map(g=>({d:g.d,v:g.kg}));
  const cards=[["Hemoglobina (g/dL)",ser("Hb"),{band:[m.hbLo,m.hbHi]}],["Kt/V (azul: laboratorio · naranja: en línea · punteada: meta)",ser("KtV"),{ref:m.ktv,dec:2,pts2:R.filter(s=>num(s.KtVOCM)!=null).map(s=>({d:s.Fecha,v:num(s.KtVOCM)}))}],["Fósforo (mg/dL)",ser("P"),{band:[m.pLo,m.pHi]}],["Calcio (mg/dL)",ser("Ca"),{ref:m.caHi}],["PTH (pg/mL)",ser("PTH"),{band:[m.pthLo,m.pthHi],dec:0}],["Albúmina (g/dL)",ser("Alb"),{ref:m.alb,dec:2}],["Potasio (mEq/L)",ser("K"),{band:[m.kLo,m.kHi]}],["Ferritina (ng/mL)",ser("Ferritina"),{dec:0}],["GID por sesión (kg), 3 meses",gid,{}],["TA sistólica pre-diálisis, 3 meses",R.filter(s=>num(s.TASPre)!=null).map(s=>({d:s.Fecha,v:num(s.TASPre)})),{ref:m.tasHi,dec:0}]].concat(p.DM==="SI"?[["Glucometría en sesión, 3 meses",R.filter(s=>num(s.Gluco)!=null).map(s=>({d:s.Fecha,v:num(s.Gluco)})),{band:[80,180],dec:0}],["HbA1c (%)",ser("HbA1c"),{ref:m.a1c}]]:[]);
  return'<div class="copyrow"><label class="f" style="min-width:280px;max-width:420px;flex:1">Paciente<select id="tpid">'+opt(act.map(p=>[p.ID,p.ID+" · "+nombre(p)]),pid)+'</select></label><span class="note">Últimos 12 meses de laboratorio y 3 meses de sesiones. Banda verde: meta individual del paciente.</span></div><div class="trendgrid">'+cards.map(([t,pts,o])=>'<div class="panel"><h3>'+esc(t)+'</h3>'+lineChart(pts,Object.assign({t},o))+'</div>').join("")+'</div>';}

/* ================= acceso vascular ================= */
function vAcc(){ensureIdx();const c=ST.corte;const act=ST.book.pac.filter(p=>epsOk(p)&&activeAt(p,c));
  const rows=act.map(p=>({p,a:accessAt(p,c)}));const cvc=rows.filter(r=>isCVC(r.a)),fav=rows.filter(r=>r.a&&!isCVC(r.a)),sd=rows.filter(r=>!r.a);
  const sinPlan=cvc.filter(r=>!r.p.RutaAcceso||r.p.RutaAcceso==="Sin valorar");const x=ctxFor(c,ST.ps,ST.eps);const its=evalInd(INDM.dia_33_adul,x);const sus=evalInd(INDM.ins_its,x);
  const nov=ST.book.acn.filter(live).filter(n=>{const p=IDX.pac.get(n.Paciente);return p&&epsOk(p)&&n.Fecha>=addMonths(c,-3);}).sort((a,b)=>b.Fecha-a.Fecha);
  let h=head("Acceso vascular","Cada catéter debe estar en un punto de la ruta: o va hacia una FAV, o tiene una exclusión con soporte. Las disfunciones, infecciones, inserciones y retiros se registran como novedad del acceso. Las bacteriemias se registran en el turno y se confirman en el módulo IAAS del sistema.",'<button type="button" class="btn" data-a="accexp">Exportar acceso vascular a Excel</button>');
  h+='<div class="tiles"><div class="tile"><span class="tv">'+act.length+'</span><span class="tl">activos al corte</span></div><div class="tile '+(cvc.length/Math.max(1,act.length)>.2?"bad":"warn")+'"><span class="tv">'+cvc.length+' <small style="font-size:14px">('+pct(cvc.length/Math.max(1,act.length))+')</small></span><span class="tl">con catéter (corte alto CAC &lt; 10 %, sin excluir)</span></div><div class="tile ok"><span class="tv">'+fav.length+'</span><span class="tl">con FAV o injerto</span></div><div class="tile '+(sinPlan.length?"bad":"ok")+'"><span class="tv">'+sinPlan.length+'</span><span class="tl">catéteres sin valorar</span></div><div class="tile '+(its.status==="bajo"?"bad":its.status==="alto"?"ok":"base")+'"><span class="tv">'+fmtVal(INDM.dia_33_adul,its.val)+'</span><span class="tl">ITS-CVC confirmadas por 1.000 días-catéter · '+esc(its.expl)+'</span></div><div class="tile warn"><span class="tv">'+fmtVal(INDM.ins_its,sus.val)+'</span><span class="tl">incluyendo sospechas sin hemocultivo positivo · '+sus.ev+' episodios</span></div></div>';
  h+='<div class="panel"><h3>Pacientes con catéter ('+cvc.length+')</h3><div class="tablebox"><table><thead><tr><th>Paciente</th><th>Acceso</th><th>Con catéter desde</th><th class="num">Meses</th><th>Ruta</th><th>Soporte</th><th>Fecha</th><th></th></tr></thead><tbody>'+
   (cvc.sort((a,b)=>RUTA.indexOf(a.p.RutaAcceso||"Sin valorar")-RUTA.indexOf(b.p.RutaAcceso||"Sin valorar")).map(({p,a})=>{const ex=RUTA_EXCL.includes(p.RutaAcceso);const n=p._acn.length?p._acn[p._acn.length-1]:null;return'<tr><td><strong>'+esc(p.ID)+'</strong><span class="sub">'+esc(nombre(p))+' · '+esc(p.EPS||"")+'</span>'+(n?'<span class="sub">Última novedad: '+esc(n.Tipo)+' · '+fd(n.Fecha)+'</span>':"")+'</td><td><span class="tag cvc">'+esc(a)+'</span></td><td><input type="date" data-r="'+p.ID+'|AccesoDesde" value="'+(p.AccesoDesde?iso(p.AccesoDesde):"")+'"'+(!p.AccesoDesde?' style="border-color:var(--warn)"':"")+'></td><td class="num">'+(p.AccesoDesde?f1(dayDiff(p.AccesoDesde,c)/30.44,1):'<span class="sd">—</span>')+'</td><td><select data-r="'+p.ID+'|RutaAcceso">'+opt(RUTA,p.RutaAcceso||"Sin valorar")+'</select></td><td><input type="text" data-r="'+p.ID+'|SoporteRuta" value="'+esc(p.SoporteRuta||"")+'" placeholder="'+(ex?"Obligatorio para excluir":"Remisión, concepto…")+'"'+(ex&&!p.SoporteRuta?' style="border-color:var(--bad)"':"")+'></td><td><input type="date" data-r="'+p.ID+'|FechaRuta" value="'+(p.FechaRuta?iso(p.FechaRuta):"")+'"></td><td><div class="copyrow" style="gap:4px;flex-wrap:nowrap"><button type="button" class="btn sm primary" data-a="rsave|'+p.ID+'">Guardar</button><button type="button" class="btn sm" data-a="acnew|'+p.ID+'">Novedad</button></div></td></tr>';}).join("")||'<tr><td colspan="8" class="empty">Ningún paciente con catéter.</td></tr>')+'</tbody></table></div><p class="note">«Con catéter desde» es la fecha de inserción del catéter actual; los meses se calculan al corte. Las tres últimas opciones de la ruta excluyen del indicador dia_10 solo si tienen soporte. KDOQI 2019 propone un plan de acceso individual en lugar de «FAV primero».</p></div>';
  h+='<div class="grid2"><div class="panel"><h3>FAV e injertos ('+fav.length+')</h3><div class="tablebox"><table><thead><tr><th>Paciente</th><th>Acceso</th><th>Desde</th><th></th></tr></thead><tbody>'+fav.map(({p,a})=>'<tr><td>'+esc(p.ID)+'<span class="sub">'+esc(nombre(p))+'</span></td><td><span class="tag fav">'+esc(a)+'</span></td><td class="mono">'+(p.AccesoDesde?fd(p.AccesoDesde):"—")+'</td><td><button type="button" class="btn sm" data-a="acnew|'+p.ID+'">Novedad</button></td></tr>').join("")+'</tbody></table></div>'+(sd.length?'<p class="note">Sin acceso registrado: '+sd.map(r=>esc(r.p.ID)).join(", ")+'</p>':"")+'</div>'+
   '<div class="panel"><h3>Novedades del acceso, últimos 3 meses ('+nov.length+')</h3>'+(nov.length?'<div class="tablebox"><table><tbody>'+nov.slice(0,40).map(n=>{const p=IDX.pac.get(n.Paciente);return'<tr><td class="mono">'+fd(n.Fecha)+'</td><td>'+esc(n.Paciente)+'<span class="sub">'+esc(nombre(p))+'</span></td><td>'+esc(n.Tipo)+(n.Detalle?'<span class="sub">'+esc(n.Detalle)+'</span>':"")+'</td></tr>';}).join("")+'</tbody></table></div>':'<p class="note">Sin novedades registradas.</p>')+'</div></div>';
  h+='<div class="panel"><h3>Bacteriemias asociadas a catéter en el periodo</h3>'+(sus.list.length?'<div class="tablebox"><table><tbody>'+sus.list.map(r=>'<tr><td>'+esc(r.p.ID)+'<span class="sub">'+esc(nombre(r.p))+'</span></td><td>'+esc(r.v)+'</td></tr>').join("")+'</tbody></table></div>':'<p class="note">Sin eventos en el periodo.</p>')+'<p class="note">Se registran como evento en el turno (o importadas del Dashboard) y se confirman en <button type="button" class="lnk" data-a="pxgo|iaas|hd">IAAS → Infecciones de hemodiálisis</button> con el hemocultivo y el microorganismo. Solo las confirmadas cuentan para el indicador CAC dia_33.</p></div>';
  return h;}
function dlgAccNov(pid){const p=IDX.pac.get(pid);openDlg("Novedad del acceso · "+pid+" · "+nombre(p),'<div class="form"><label class="f">Novedad<select id="an_t">'+opt(ACC_NOV,"","Seleccione…")+'</select></label><label class="f">Fecha<input type="date" id="an_f" value="'+iso(TODAY())+'"></label><label class="f">Acceso resultante<select id="an_a">'+opt(ACCESOS,"","Sin cambio")+'</select></label><label class="f wide">Detalle<input type="text" id="an_d" placeholder="Hallazgo, conducta, remisión"></label></div><p class="note">Acceso actual: '+esc(accessAt(p,ST.corte)||"sin registro")+'. Si la novedad cambia el acceso, se actualiza la fecha desde la cual lo tiene.</p>',"Registrar",()=>{if(needUser())return"Falta el usuario que registra.";const t=$("an_t").value,f=pdate($("an_f").value);if(!t||!f)return"Elija la novedad y la fecha.";
  const res=$("an_a").value||ACC_NOV_RES[t]||"";addRec("acn","AC-",{Paciente:pid,Fecha:f,Tipo:t,Detalle:$("an_d").value.trim(),AccesoResultante:res});if(res)updRec("pac",p,{AccesoActual:res,AccesoDesde:f});if(t==="Creación de FAV")updRec("pac",p,{RutaAcceso:"FAV creada, en maduración",FechaRuta:f});if(t==="Remisión a cirugía vascular")updRec("pac",p,{RutaAcceso:"Remitido a cirugía vascular",FechaRuta:f});reindex();render();toast("Novedad del acceso registrada.");});}
function accExport(){ensureIdx();const c=ST.corte;const P=ST.book.pac.filter(p=>epsOk(p)&&activeAt(p,c));
  exportSheets("Acceso_vascular_"+iso(c)+".xlsx",[["Pacientes",P,PID_COLS.concat([["Turno",p=>p.Turno],["Acceso al corte",p=>accessAt(p,c)],["Acceso desde",p=>p.AccesoDesde],["Meses con el acceso",p=>p.AccesoDesde?Math.round(dayDiff(p.AccesoDesde,c)/30.44*10)/10:""],["Acceso al iniciar HD",p=>p.AccesoInicial],["Ruta",p=>p.RutaAcceso],["Soporte",p=>p.SoporteRuta],["Fecha soporte",p=>p.FechaRuta],["Días-catéter en el periodo",p=>catDays(p,ST.ps,c)],["ITS-CVC en el periodo",p=>p._evt.filter(e=>e.Tipo===ITS&&e.Fecha>=ST.ps&&e.Fecha<=c).length],["Última novedad",p=>p._acn.length?p._acn[p._acn.length-1].Tipo:""],["Fecha última novedad",p=>p._acn.length?p._acn[p._acn.length-1].Fecha:""],["Estado",p=>p.Estado]])],
   ["Novedades",ST.book.acn.filter(live).filter(n=>{const p=IDX.pac.get(n.Paciente);return p&&epsOk(p);}).sort((a,b)=>b.Fecha-a.Fecha),[["Fecha",n=>n.Fecha],["ID",n=>n.Paciente],["Paciente",n=>nombre(IDX.pac.get(n.Paciente))],["Novedad",n=>n.Tipo],["Acceso resultante",n=>n.AccesoResultante],["Detalle",n=>n.Detalle],["Registró",n=>n.Usuario]]],
   ["Bacteriemias",ST.book.evt.filter(live).filter(e=>e.Tipo===ITS),[["Fecha",e=>e.Fecha],["ID",e=>e.Paciente],["Paciente",e=>nombre(IDX.pac.get(e.Paciente))],["Hemocultivo",e=>e.Hemocultivo],["Microorganismo",e=>e.Microorganismo],["Resuelto",e=>e.Resuelto],["Conducta",e=>e.Conducta]]]]);}

/* ================= calidad de diálisis y semáforo de riesgo ================= */
function vSem(){ensureIdx();const c=ST.corte;const sub=ST.ui.semsub||"cal";
  let h=head("Calidad de diálisis y riesgo","Calidad de diálisis: matriz de evaluación integral de las últimas 4 semanas. Semáforo de riesgo: priorización para nefrología con laboratorios y acceso. Ambos son rúbricas institucionales, no escalas validadas.")+'<div class="seg" role="group">'+[["cal","Calidad de diálisis"],["sem","Semáforo de riesgo"]].map(([k,l])=>'<button type="button" data-a="semsub|'+k+'" aria-pressed="'+(sub===k)+'">'+l+'</button>').join("")+'</div>';
  return h+(sub==="cal"?calView(c):semView(c));}
function calView(c){const R=ST.book.pac.filter(p=>epsOk(p)&&activeAt(p,c)).map(p=>({p,q:calidadDe(p,c)}));const f=ST.ui.calf||"all";const cats=["Excelente","Bueno","Regular","Malo","Sin datos suficientes"];
  const R2=(f==="all"?R:R.filter(r=>r.q.cat===f)).sort((a,b)=>cats.indexOf(b.q.cat)-cats.indexOf(a.q.cat)||b.q.tot-a.q.tot);const cell=(v)=>v==null?'<td class="num sd">—</td>':'<td class="num"><span class="pt p'+v+'">'+v+'</span></td>';
  let h='<div class="tiles">'+cats.map(k=>'<div class="tile '+CAL_CLASS[k]+'"><span class="tv">'+R.filter(r=>r.q.cat===k).length+'</span><span class="tl">'+k.toLowerCase()+'</span></div>').join("")+'</div>';
  h+='<details class="panel hist" open><summary>Cómo se califica</summary><p class="note">Diez dominios de la matriz de evaluación integral. Cada uno da 0 (óptimo), 1 (intermedio) o 2 (deficiente). Kt/V, GID, UFR, PAS mínima, sesiones perdidas y acortadas e hipotensiones salen del turno y del laboratorio; congestión, situación del acceso, recuperación pos-HD y fatiga se diligencian en la Valoración mensual. Excelente: 0-2 puntos sin dominios deficientes. Bueno: hasta 5 con un dominio deficiente como máximo. Regular: 6-9. Malo: más de 9, tres o más dominios deficientes o Kt/V &lt; 1,0. Con 4 o más dominios sin dato: «sin datos suficientes».</p><div class="tablebox"><table><thead><tr><th>Dominio</th><th>0 · 1 · 2</th></tr></thead><tbody>'+CAL_DOM.map(([k,l,t])=>'<tr><td>'+esc(l)+'</td><td style="font-size:13px">'+esc(t)+'</td></tr>').join("")+'</tbody></table></div><p class="note">Umbrales apoyados en KDOQI 2015 (Kt/V), Flythe 2011 (UFR &gt; 13 mL/kg/h), Kalantar-Zadeh 2009 (GID), Rayner 2014 (tiempo de recuperación) y Saran 2003 (sesiones perdidas); la combinación en una categoría es institucional.</p></details>';
  h+='<div class="seg" role="group">'+[["all","Todos"]].concat(cats.map(k=>[k,k])).map(([k,l])=>'<button type="button" data-a="calf|'+k+'" aria-pressed="'+(f===k)+'">'+l+'</button>').join("")+'</div>';
  h+='<div class="panel tablebox" style="padding:0"><table class="caltab"><thead><tr><th>Paciente</th>'+CAL_DOM.map(([k,l])=>'<th class="num" title="'+esc(l)+'">'+({ktv:"Kt/V",gid:"GID",ufr:"UFR",hemo:"Hipot.",sint:"Sínt.",cong:"Cong.",acc:"Acceso",rec:"Recup.",fat:"Fatiga",adh:"Adher."}[k]||esc(l))+'</th>').join("")+'<th class="num">Total</th><th>Calidad</th><th>Revisión</th></tr></thead><tbody>'+
   R2.map(({p,q})=>'<tr><td><strong>'+esc(p.ID)+'</strong><span class="sub">'+esc(nombre(p))+'</span><span class="sub">Kt/V '+(q.auto.ktv!=null?f1(q.auto.ktv,2):"—")+' · GID '+(q.auto.gidPct!=null?f1(q.auto.gidPct)+" %":"—")+' · UFR '+(q.auto.ufrMax!=null?f1(q.auto.ufrMax):"—")+(q.val?' · valoración '+fd(q.val.Fecha):' · sin valoración reciente')+'</span></td>'+CAL_DOM.map(([k])=>cell(q.pt[k])).join("")+'<td class="num sc">'+q.tot+'</td><td><span class="st '+CAL_CLASS[q.cat]+'">'+esc(q.cat)+'</span></td><td style="font-size:13px">'+(q.revision==="Sí"?'<strong>Sí</strong><span class="sub">'+esc(q.motivo)+'</span>':"No")+'</td></tr>').join("")+'</tbody></table></div>';
  return h;}
function semView(c){const f=ST.ui.sf||"all";
  const R=ST.book.pac.filter(p=>epsOk(p)&&activeAt(p,c)).map(p=>({p,s:semaforo(p,c)})).sort((a,b)=>b.s.tot-a.s.tot||b.s.sd.length-a.s.sd.length);
  const n=l=>R.filter(r=>r.s.lvl===l).length;const R2=f==="all"?R:f==="sd"?R.filter(r=>r.s.sd.length):R.filter(r=>r.s.lvl===f);
  const cell=(v,s,fm)=>v==null?'<td class="num sd">sin dato</td>':'<td class="num">'+(fm?fm(v):f1(v))+(s?'<span class="sub">+'+s+'</span>':"")+'</td>';
  let h='<div class="tiles"><div class="tile bad"><span class="tv">'+n("alto")+'</span><span class="tl">riesgo alto (6 o más)</span></div><div class="tile warn"><span class="tv">'+n("medio")+'</span><span class="tl">riesgo medio (3 a 5)</span></div><div class="tile ok"><span class="tv">'+n("bajo")+'</span><span class="tl">riesgo bajo (0 a 2)</span></div><div class="tile base"><span class="tv">'+R.filter(r=>r.s.sd.length).length+'</span><span class="tl">con datos faltantes</span></div></div>';
  h+='<details class="panel hist" open><summary>Cómo se asigna el puntaje</summary><div class="tablebox"><table><thead><tr><th>Variable</th><th class="num">0 puntos</th><th class="num">1 punto</th><th class="num">2 puntos</th><th class="num">3-4 puntos</th></tr></thead><tbody><tr><td>Albúmina (g/dL)</td><td class="num">≥ 4</td><td class="num">—</td><td class="num">3,5-3,99</td><td class="num">4 si &lt; 3,5</td></tr><tr><td>Hemoglobina (g/dL)</td><td class="num">≥ 10</td><td class="num">8-9,9</td><td class="num">—</td><td class="num">3 si &lt; 8</td></tr><tr><td>Fósforo (mg/dL)</td><td class="num">&lt; 6</td><td class="num">6-7,5</td><td class="num">&gt; 7,5</td><td class="num">—</td></tr><tr><td>TAS pre-diálisis (promedio 30 días)</td><td class="num">&lt; 140</td><td class="num">140-160</td><td class="num">&gt; 160</td><td class="num">—</td></tr><tr><td>HbA1c en DM (%)</td><td class="num">&lt; 7</td><td class="num">7-9</td><td class="num">&gt; 9</td><td class="num">—</td></tr><tr><td>Acceso</td><td class="num">FAV o injerto</td><td class="num">—</td><td class="num">CVC tunelizado</td><td class="num">3 si CVC temporal</td></tr></tbody></table></div><p class="note">Suma: 0-2 bajo, 3-5 medio, 6 o más alto. Laboratorios del último trimestre, HbA1c de 6 meses. Un dato faltante no suma: se muestra aparte para que no parezca riesgo bajo. Puntaje institucional definido por la unidad, no validado.</p></details>';
  h+='<div class="seg" role="group">'+[["all","Todos"],["alto","Alto"],["medio","Medio"],["bajo","Bajo"],["sd","Con datos faltantes"]].map(([k,l])=>'<button type="button" data-a="sf|'+k+'" aria-pressed="'+(f===k)+'">'+l+'</button>').join("")+'</div>';
  h+='<div class="panel tablebox" style="padding:0"><table><thead><tr><th>Paciente</th><th class="num">Hb</th><th class="num">Albúmina</th><th class="num">Fósforo</th><th class="num">TAS</th><th class="num">HbA1c</th><th>Acceso</th><th class="num">Puntaje</th><th>Nivel</th><th>Alertas</th></tr></thead><tbody>'+
   R2.map(({p,s})=>'<tr><td><strong>'+esc(p.ID)+'</strong><span class="sub">'+esc(nombre(p))+' · '+esc(p.EPS||"")+'</span></td>'+cell(s.hb,s.sc.hb)+cell(s.alb,s.sc.alb,v=>f1(v,2))+cell(s.P,s.sc.p)+cell(s.tas,s.sc.tas,v=>f1(v,0))+(p.DM==="SI"?cell(s.a1c,s.sc.a1c):'<td class="num sd">no DM</td>')+'<td>'+(s.acc?'<span class="tag '+(isCVC(s.acc)?"cvc":"fav")+'">'+esc(s.acc)+'</span>':'<span class="sd">sin dato</span>')+'</td><td class="num sc">'+s.tot+'</td><td><span class="lvl '+s.lvl+'">'+s.lvl.toUpperCase()+'</span>'+(s.sd.length?'<span class="sub">falta: '+esc(s.sd.join(", "))+'</span>':"")+'</td><td style="font-size:13px">'+(s.al.map(esc).join("<br>")||'<span class="sub">—</span>')+'</td></tr>').join("")+'</tbody></table></div>';
  return h;}

/* ================= indicadores ================= */
function spark(pts,def){const v=pts.map(p=>p.v).filter(x=>x!=null);if(v.length<2)return'<span class="sd">—</span>';const W=96,H=26;const mx=Math.max(...v),mn=Math.min(...v);const sp=mx-mn||1;const X=i=>i*(W-6)/(pts.length-1)+3,Y=x=>H-3-(x-mn)/sp*(H-8);
  const d=pts.map((p,i)=>p.v==null?null:[X(i),Y(p.v)]).filter(Boolean);return'<svg class="spark" viewBox="0 0 '+W+' '+H+'" aria-hidden="true"><polyline fill="none" stroke="var(--accent)" stroke-width="1.6" points="'+d.map(q=>q.join(",")).join(" ")+'"/><circle cx="'+d[d.length-1][0]+'" cy="'+d[d.length-1][1]+'" r="2.6" fill="var(--accent)"/></svg>';}
function metaOf(def){const m=(ST.book.cfgv.metas||{})[def.c];return m!=null&&m!==""?num(m):(def.meta!=null?def.meta:null);}
function metaTxt(def){const m=metaOf(def);const cac=def.cuts?(def.t==="rate"?"CAC alto < "+def.cuts[0]:def.dir==="down"?"CAC alto < "+def.cuts[0]+" %":"CAC alto > "+def.cuts[0]+" %"):"";const ins=m!=null?"Institucional "+(def.dir==="down"?"≤ ":"≥ ")+m+(def.t==="pct"?" %":""):"";return[cac,ins].filter(Boolean).join(" · ")||(def.inst?"Sin meta definida":"Línea de base");}
function bigChart(pts,def){const W=640,H=220,L=46,R=16,T=16,B=34;const isP=def.t==="pct";const vals=pts.map(p=>p.v).filter(x=>x!=null).map(v=>isP?v*100:v);
  const mi=metaOf(def);let mx=isP?100:Math.max(1,...vals,...(def.cuts||[]),mi||0)*1.15;const X=i=>L+i*(W-L-R)/Math.max(1,pts.length-1),Y=v=>T+(1-v/mx)*(H-T-B);
  const M=["ene","feb","mar","abr","may","jun","jul","ago","sep","oct","nov","dic"];let s='<svg class="chart" viewBox="0 0 '+W+' '+H+'" role="img" aria-label="Tendencia mensual de '+esc(def.c)+'">';
  const ticks=isP?[0,25,50,75,100]:[0,mx/2,mx].map(v=>Math.round(v*100)/100);ticks.forEach(t=>{s+='<line x1="'+L+'" x2="'+(W-R)+'" y1="'+Y(t)+'" y2="'+Y(t)+'" stroke="var(--line)"/><text class="ax" x="'+(L-6)+'" y="'+(Y(t)+4)+'" text-anchor="end">'+(isP?t+" %":f1(t,1))+'</text>';});
  if(def.cuts){const cv=def.t==="rate"?[def.cuts[0]]:def.dir==="down"?[def.cuts[0]]:[def.cuts[0]];cv.forEach(v=>{s+='<line x1="'+L+'" x2="'+(W-R)+'" y1="'+Y(v)+'" y2="'+Y(v)+'" stroke="var(--ok)" stroke-dasharray="5 4"/><text class="ax" x="'+(W-R)+'" y="'+(Y(v)-5)+'" text-anchor="end" style="fill:var(--ok)">corte alto CAC '+(isP?v+" %":v)+'</text>';});}
  if(mi!=null){s+='<line x1="'+L+'" x2="'+(W-R)+'" y1="'+Y(mi)+'" y2="'+Y(mi)+'" stroke="var(--warn)" stroke-dasharray="2 4" stroke-width="1.6"/><text class="ax" x="'+(L+4)+'" y="'+(Y(mi)-5)+'" style="fill:var(--warn)">meta institucional '+(isP?mi+" %":mi)+'</text>';}
  if(!def.cuts&&mi==null)s+='<text class="ax" x="'+(W-R)+'" y="'+(T+10)+'" text-anchor="end">Línea de base: sin corte CAC ni meta institucional definida</text>';
  const d=pts.map((p,i)=>p.v==null?null:[X(i),Y(isP?p.v*100:p.v),p]).filter(Boolean);
  if(d.length>1)s+='<polyline fill="none" stroke="var(--accent)" stroke-width="2.4" stroke-linejoin="round" points="'+d.map(q=>q[0]+","+q[1]).join(" ")+'"/>';
  d.forEach((q,i)=>{const last=i===d.length-1;s+='<circle cx="'+q[0]+'" cy="'+q[1]+'" r="'+(last?4.5:3)+'" fill="var(--accent)" stroke="#fff" stroke-width="1.5"><title>'+fd(q[2].d)+': '+fmtVal(def,q[2].v)+' ('+q[2].n+'/'+(def.t==="rate"?f1(q[2].dd,0):q[2].dd)+')</title></circle>';if(last)s+='<text class="val" x="'+q[0]+'" y="'+(q[1]-10)+'" text-anchor="end">'+fmtVal(def,q[2].v)+'</text>';});
  pts.forEach((p,i)=>{s+='<text class="ax" x="'+X(i)+'" y="'+(H-12)+'" text-anchor="middle">'+M[p.d.getMonth()]+' '+String(p.d.getFullYear()).slice(2)+'</text>';});
  return s+'</svg>';}
function vInd(){ensureIdx();const x=ctxFor(ST.corte,ST.ps,ST.eps);const R=IND.map(d=>{const r=evalInd(d,x);r.tr=trendPoints(d,6);return r;});
  const cnt=s=>R.filter(r=>!r.def.inst&&r.status===s).length;
  let h=head("Indicadores CAC 2026 · hemodiálisis","Corte "+fd(ST.corte)+" · periodo desde "+fd(ST.ps)+(ST.eps?" · "+esc(ST.eps):" · todas las EPS")+". Denominador: adultos en HD al corte con 90 días o más en diálisis. Un dato faltante cuenta en el denominador y no en el numerador, como en la ficha.",'<button type="button" class="btn" data-a="corfreeze">Congelar este corte</button>');
  h+='<div class="tiles"><div class="tile ok"><span class="tv">'+cnt("alto")+'</span><span class="tl">en cumplimiento alto</span></div><div class="tile warn"><span class="tv">'+cnt("medio")+'</span><span class="tl">en cumplimiento medio</span></div><div class="tile bad"><span class="tv">'+cnt("bajo")+'</span><span class="tl">en cumplimiento bajo</span></div><div class="tile base"><span class="tv">'+cnt("base")+'</span><span class="tl">línea de base (sin corte CAC)</span></div><div class="tile"><span class="tv">'+popCut(ST.corte,ST.eps).length+'</span><span class="tl">adultos HD al corte con 90 días</span></div></div>';
  h+='<div class="panel tablebox" style="padding:0"><table class="indt"><thead><tr><th>Código</th><th>Indicador</th><th class="num">Num / den</th><th class="num">Resultado</th><th>Meta o referencia</th><th>Semáforo CAC</th><th class="num">Sin dato</th><th>Últimos 6 meses</th></tr></thead><tbody>'+
   R.map(r=>{const d=r.def;const sel=ST.sel.ind===d.c;const w=d.t==="pct"&&r.val!=null?Math.min(100,r.val*100):0;return'<tr data-a="isel|'+d.c+'" class="'+(sel?"sel":"")+'"><td class="mono" style="white-space:nowrap">'+esc(d.c.replace("_adul",""))+'<span class="sub"><span class="tag '+(d.inst?"inst":"cac")+'">'+(d.inst?"Institucional":"CAC 2026")+'</span></span></td><td>'+esc(d.n)+'<span class="sub">'+esc(d.win)+'</span></td><td class="num">'+(d.t==="rate"?r.n+' / '+f1(r.d,d.c==="dia_33_adul"?0:1):r.n+' / '+r.d)+'</td><td class="num"><strong>'+fmtVal(d,r.val)+'</strong>'+(d.t==="rate"?'<span class="sub">'+esc(d.unit)+'</span>':'<span class="bar"><span style="width:'+w+'%"></span></span>')+'</td><td style="font-size:12.5px">'+esc(metaTxt(d))+(()=>{const mi=metaOf(d);if(mi==null||r.val==null)return"";const v=d.t==="pct"?r.val*100:r.val;const ok=d.dir==="down"?v<=mi:v>=mi;return'<span class="sub" style="color:var('+(ok?"--ok":"--bad")+')">'+(ok?"cumple meta institucional":"no cumple meta institucional")+'</span>';})()+'</td><td><span class="st '+r.status+'">'+STATUS_TXT[r.status]+'</span></td><td class="num">'+((r.sd&&r.sd.length)||"")+'</td><td>'+spark(r.tr,d)+'</td></tr>';}).join("")+'</tbody></table></div>';
  const r=R.find(z=>z.def.c===ST.sel.ind)||R[0];h+=indDetail(r);
  const C=ST.book.cor;if(C.length)h+='<div class="panel"><h3>Cortes congelados ('+C.length+')</h3><div class="tablebox"><table><thead><tr><th>Corte</th><th>EPS</th><th>Congeló</th>'+IND.filter(d=>!d.inst).slice(0,8).map(d=>'<th class="num">'+esc(d.c.replace("_adul",""))+'</th>').join("")+'</tr></thead><tbody>'+C.slice().reverse().map(k=>{let D={};try{D=JSON.parse(k.Datos);}catch(e){}return'<tr><td class="mono">'+fd(k.FechaCorte)+'</td><td>'+esc(k.EPS||"Todas")+'</td><td><span class="sub">'+esc(k.Usuario)+' · '+esc(k.Registrado)+'</span></td>'+IND.filter(d=>!d.inst).slice(0,8).map(d=>{const v=D[d.c];return'<td class="num">'+(v&&v.v!=null?fmtVal(d,v.v):"—")+'</td>';}).join("")+'</tr>';}).join("")+'</tbody></table></div><p class="note">El corte congelado conserva el valor que se reportó aunque después se corrijan datos. El detalle completo queda en la hoja «Cortes» del libro.</p></div>';
  return h;}
function indDetail(r){const d=r.def;const pl=(arr,fn)=>arr&&arr.length?'<div class="tablebox"><table><tbody>'+arr.map(fn).join("")+'</tbody></table></div>':'<p class="note">Ninguno.</p>';
  const row=x=>'<tr><td class="mono">'+esc(x.p.ID)+'</td><td>'+esc(nombre(x.p))+'<span class="sub">'+esc(x.p.EPS||"")+'</span></td><td>'+esc(x.v==null?"":typeof x.v==="number"?f1(x.v,2):x.v)+'</td></tr>';
  let h='<div class="panel"><div class="inddet"><div class="hero"><span class="tag '+(d.inst?"inst":"cac")+'">'+esc(d.c)+'</span><div class="hn">'+esc(d.n)+'</div><div class="hv">'+fmtVal(d,r.val)+'</div><div class="note">'+(d.t==="rate"?esc(d.unit)+" · ":"")+esc(r.expl||(r.n+" de "+r.d))+'</div><p><span class="st '+r.status+'">'+STATUS_TXT[r.status]+'</span></p>'+
   '<dl class="ficha"><dt>Ventana</dt><dd>'+esc(d.win)+'</dd><dt>Fuente</dt><dd>'+esc(d.src)+'</dd>'+(d.cuts?'<dt>Corte CAC</dt><dd>'+(d.t==="rate"?"Alto < "+d.cuts[0]+"; bajo ≥ "+d.cuts[0]:d.dir==="down"?"Alto < "+d.cuts[0]+" %; medio "+d.cuts[0]+"-"+d.cuts[1]+" %; bajo > "+d.cuts[1]+" %":"Alto > "+d.cuts[0]+" %; medio "+d.cuts[1]+"-"+d.cuts[0]+" %; bajo < "+d.cuts[1]+" %")+'</dd>':'<dt>Corte</dt><dd>'+(d.inst?"Meta institucional por definir":"Línea de base (la CAC fijará el corte)")+'</dd>')+'<dt>Meta</dt><dd>'+esc(metaTxt(d))+' · la meta institucional se edita en Referencia</dd>'+(d.ex?'<dt>Exclusiones</dt><dd>'+esc(d.ex)+'</dd>':"")+(d.nota?'<dt>Nota</dt><dd>'+esc(d.nota)+'</dd>':"")+'</dl></div>'+
   '<div style="min-width:0"><h3>Tendencia · cierre de cada mes'+(d.t==="rate"||/Periodo|Incidentes/.test(d.win)?" (periodo móvil de 12 meses)":"")+'</h3>'+bigChart(r.tr,d)+(d.t==="rate"||/Periodo|Incidentes/.test(d.win)?'<p class="note">El valor grande usa el periodo elegido arriba (desde '+fd(ST.ps)+'). Cada punto de la tendencia usa los 12 meses anteriores a ese cierre, por eso pueden diferir.</p>':"")+'</div></div>';
  if(d.t==="rate")h+='<details class="hist" open><summary>Eventos que cuentan ('+r.list.length+')</summary>'+pl(r.list,row)+'</details>';
  else{h+='<div class="grid2" style="margin-top:10px"><details class="hist" open><summary>Numerador ('+r.num.length+')</summary>'+pl(r.num,row)+'</details><details class="hist" open><summary>Denominador sin numerador ('+r.den.filter(x=>!r.num.some(n=>n.p===x.p)).length+')</summary>'+pl(r.den.filter(x=>!r.num.some(n=>n.p===x.p)),row)+'</details></div>';
    if(r.excl.length)h+='<details class="hist"><summary>Excluidos ('+r.excl.length+')</summary>'+pl(r.excl.map(e=>({p:e.p,v:e.why})),row)+'</details>';}
  return h+'</div>';}
function corFreeze(){if(needUser())return;const x=ctxFor(ST.corte,ST.ps,ST.eps);const D={};IND.forEach(d=>{const r=evalInd(d,x);D[d.c]={v:r.val,n:r.n,d:r.d,s:r.status};});
  addRec("cor","C-",{FechaCorte:ST.corte,InicioPeriodo:ST.ps,EPS:ST.eps||"",Datos:JSON.stringify(D)});toast("Corte del "+fd(ST.corte)+" congelado.");render();}

/* ================= alertas ================= */
function vAlert(){const A=alertas();const pr=p=>'<strong>'+esc(p.ID)+'</strong><span class="sub">'+esc(nombre(p))+' · '+esc(p.EPS||"")+' · Tel. '+esc(p.Telefono||"—")+'</span>';
  const sec=(t,sub,rows,cols,lvl)=>'<div class="panel"><div class="mhead"><h3 style="margin:0">'+t+' ('+rows.length+')</h3></div>'+(sub?'<p class="note" style="margin:4px 0 8px">'+sub+'</p>':"")+(rows.length?'<div class="tablebox"><table><tbody>'+rows.map(r=>'<tr>'+cols.map(c=>'<td>'+c(r)+'</td>').join("")+'</tr>').join("")+'</tbody></table></div>':'<p class="note">Sin pendientes.</p>')+'</div>';
  let h=head("Alertas","Lo que hay que hacer hoy, calculado al "+fd(ST.corte)+". Cada alerta se cierra con un registro, no a mano.");
  h+=sec("Búsqueda activa tras inasistencia","Inasistencias de los últimos 14 días sin contacto registrado después. Faltar a una o más sesiones al mes se asoció con mayor mortalidad en DOPPS (Saran 2003, observacional). Estos contactos son el soporte de abandono que pide la CAC.",A.busq,[r=>pr(r.p),r=>'No asistió el '+fd(r.s.Fecha)+(r.s.Motivo?'<span class="sub">'+esc(r.s.Motivo)+'</span>':""),r=>(typeof pxCompose==="function"&&PX.user?'<button type="button" class="btn sm" data-a="pxn|0|'+r.p.ID+'|'+fd(r.s.Fecha)+(r.s.Motivo?' · '+r.s.Motivo:'')+'">Notificar a Trabajo social</button> ':'')+'<button type="button" class="btn sm primary" data-a="ctc|'+r.p.ID+'|'+r.s.ID+'">Registrar contacto</button>']);
  h+=sec("Sin sesión realizada en 7 días o más","Pacientes activos sin hospitalización ni viaje abierto. A los 30 días con contactos documentados se evalúa abandono.",A.sinses.sort((a,b)=>b.dias-a.dias),[r=>pr(r.p),r=>'<span class="mono">'+r.dias+' días</span><span class="sub">'+(r.last?"Última: "+fd(r.last):"Sin sesiones registradas")+'</span>',r=>(typeof pxCompose==="function"&&PX.user?'<button type="button" class="btn sm" data-a="pxn|1|'+r.p.ID+'|'+r.dias+' días">Notificar a Trabajo social</button> ':'')+'<button type="button" class="btn sm" data-a="ctc|'+r.p.ID+'|">Registrar contacto</button>']);
  h+=sec("Mínimo contractual de sesiones del mes","Comparado con el mínimo de sesiones por EPS (Referencia). La meta clínica es la prescripción; esta alerta es para que la búsqueda activa llegue a tiempo.",A.minimo,[r=>pr(r.p),r=>esc(r.tipo),r=>'<span class="mono">'+r.real+' realizadas + '+r.rest+' por hacer · mínimo '+r.min+'</span>']);
  h+=sec("Hb mayor de 13 g/dL","KDIGO 2026: con AEE no mantener Hb ≥ 11,5; buscar Hb ≥ 13 aumenta el riesgo de ACV y de pérdida del acceso. Verifique la dosis de AEE.",A.hb13,[r=>pr(r.p),r=>'<span class="mono">'+f1(r.v)+' g/dL</span><span class="sub">'+fd(r.d)+'</span>']);
  h+=sec("Catéter sin plan de acceso o exclusión sin soporte","",A.cvcplan,[r=>pr(r.p),r=>esc(r.acc)+'<span class="sub">'+(r.sop?"Exclusión sin soporte":"Ruta: sin valorar")+'</span>',r=>'<button type="button" class="lnk" data-a="go|acc">Ir a acceso vascular</button>']);
  h+=sec("Sospecha de ITS-CVC sin hemocultivo","Sin hemocultivo positivo el evento no cuenta para dia_33. Se confirma en el módulo IAAS.",A.its,[r=>pr(r.p),r=>fd(r.e.Fecha)+' · hemocultivo '+esc(r.e.Hemocultivo||"sin dato"),r=>'<button type="button" class="lnk" data-a="pxgo|iaas|hd">Confirmar en IAAS</button>']);
  h+=sec("Vacunación VHB que requiere acción","Dosis vencidas, anti-HBs de control o anual pendiente, revacunación, refuerzo y susceptibles sin vacunar (CDC 2001; GSH-PT-001).",A.vac,[r=>pr(r.p),r=>'<span class="st '+r.s.lvl+'">'+esc(vacEtiqueta(r.s.code))+'</span><span class="sub">'+esc(r.s.txt)+'</span>',r=>'<button type="button" class="lnk" data-a="go|vac">Ir a vacunación</button>']);
  h+=sec("Estudios con control vencido","Estudios o procedimientos con fecha de próximo control ya cumplida y sin un estudio más reciente del mismo tipo.",A.est,[r=>pr(r.p),r=>esc(r.e.Nombre)+'<span class="sub">control '+fd(r.e.ProximoControl)+(r.e.Seguimiento?' · '+esc(r.e.Seguimiento):'')+'</span>',r=>'<button type="button" class="lnk" data-a="psel|'+r.p.ID+'">Ver ficha</button>']);
  h+=sec("Ganancia interdialítica promedio mayor de 4 %","Promedio de los últimos 8 intervalos. Revisar peso seco, educación en líquidos y sodio, y considerar sesión extra.",A.gid.sort((a,b)=>b.g.pct-a.g.pct),[r=>pr(r.p),r=>'<span class="mono">'+f1(r.g.kg)+' kg · '+f1(r.g.pct)+' %</span><span class="sub">máximo '+f1(r.g.max)+' kg</span>']);
  h+=sec("Hipoglucemias en sesión (últimos 14 días)","Glucometría menor de 70 mg/dL. Ajustar insulina o hipoglucemiantes en días de diálisis.",A.hipo,[r=>pr(r.p),r=>r.gl.hipo+' de '+r.gl.n+' glucometrías &lt; 70 · promedio '+f1(r.gl.avg,0)]);
  h+=sec("Sin valoración mensual este mes","Pacientes activos sin valoración registrada en el mes del corte.",A.val,[r=>pr(r.p),r=>r.v?'Última: '+fd(r.v.Fecha):'Nunca valorado en la herramienta',r=>'<button type="button" class="lnk" data-a="vgo|'+r.p.ID+'">Valorar</button>']);
  h+=sec("Hospitalizaciones abiertas","Registre el egreso para que cuente en dia_31 y para reanudar el cálculo de asistencia.",A.hosp,[r=>pr(r.p),r=>'Desde '+fd(r.n.Inicio)+'<span class="sub">'+esc(r.n.Descripcion||"")+'</span>',r=>'<button type="button" class="lnk" data-a="novclose|'+r.n.ID+'">Registrar egreso</button>']);
  h+=sec("Eventos sin cierre","",A.evab,[r=>pr(r.p),r=>fd(r.e.Fecha)+' · '+esc(r.e.Tipo)+'<span class="sub">'+esc(r.e.Resuelto||"")+'</span>',r=>'<button type="button" class="lnk" data-a="evclose|'+r.e.ID+'">Cerrar evento</button>']);
  h+='<div class="alert'+(A.venc?" warn":"")+'"><p>'+A.venc+' paraclínicos vencidos según la periodicidad institucional. <button type="button" class="lnk" data-a="go|lab">Ver calendario</button></p></div>';
  return h;}

