function vCal(){const Q=calidad();const G={};Q.forEach(q=>{(G[q.g]=G[q.g]||[]).push(q);});
  let h=head("Calidad del dato","Lo que impide calcular bien un indicador o una factura. Se corrige en la pestaña de origen; nada se borra.");
  if(ST.imp&&ST.imp.warn&&ST.imp.warn.length)h+='<details class="panel hist" open><summary>Avisos de la importación de «'+esc(ST.imp.fn)+'» ('+ST.imp.warn.length+')</summary><ul class="note">'+ST.imp.warn.map(w=>'<li>'+esc(w)+'</li>').join("")+'</ul><p class="note">Estos avisos no se guardan en el libro: resuélvalos antes de descargarlo o anótelos.</p></details>';
  h+='<div class="tiles">'+Object.entries(G).map(([g,a])=>'<div class="tile '+(a.some(x=>x.lvl==="bad")?"bad":"warn")+'"><span class="tv">'+a.length+'</span><span class="tl">'+esc(g)+'</span></div>').join("")+(Q.length?"":'<div class="tile ok"><span class="tv">0</span><span class="tl">hallazgos</span></div>')+'</div>';
  Object.entries(G).forEach(([g,a])=>{h+='<details class="panel hist" '+(a.some(x=>x.lvl==="bad")?"open":"")+'><summary>'+esc(g)+' ('+a.length+')</summary><div class="tablebox"><table><tbody>'+a.slice(0,300).map(q=>'<tr><td style="width:24px"><span class="st '+(q.lvl==="bad"?"bad":"warn")+'">'+(q.lvl==="bad"?"!":"·")+'</span></td><td class="mono">'+(q.p&&q.p.ID&&IDX.pac.get(q.p.ID)?'<button type="button" class="lnk" data-a="psel|'+esc(q.p.ID)+'">'+esc(q.p.ID)+'</button>':esc(q.p?q.p.ID:""))+'</td><td>'+esc(q.t)+'</td></tr>').join("")+'</tbody></table></div>'+(a.length>300?'<p class="note">Se muestran 300 de '+a.length+'.</p>':"")+'</details>';});
  const L=ST.book.log.slice(-40).reverse();h+='<details class="panel hist"><summary>Bitácora: últimos 40 cambios</summary><div class="tablebox"><table><thead><tr><th>Fecha y hora</th><th>Usuario</th><th>Acción</th><th>Hoja</th><th>Registro</th><th>Detalle</th></tr></thead><tbody>'+L.map(l=>'<tr><td class="mono">'+esc(l.FechaHora)+'</td><td>'+esc(l.Usuario)+'</td><td>'+esc(l.Accion)+'</td><td>'+esc(l.Hoja)+'</td><td class="mono">'+esc(l.Registro)+'</td><td style="font-size:13px">'+esc(String(l.Detalle||"").slice(0,200))+'</td></tr>').join("")+'</tbody></table></div></details>';
  return h;}


