const SP_CAT=["Caída","Medicación","Identificación del paciente","Acceso vascular","Hemorragia","Infección asociada a la atención","Error de dializado o de máquina","Reacción al dializador","Embolismo aéreo","Desconexión de líneas","Hipotensión severa","Otro"];
const SP_SEV=["Leve","Moderado","Grave","Centinela"];
const SP_EST=["Abierto","En análisis","Plan de mejora en curso","Cerrado"];
const ATB=["Vancomicina","Cefazolina","Ceftazidima","Cefepime","Piperacilina-tazobactam","Meropenem","Gentamicina","Amikacina","Ciprofloxacina","Ampicilina-sulbactam","Clindamicina","Linezolid","Daptomicina","Trimetoprim-sulfametoxazol","Fluconazol","Otro"];
const ATB_IND=["ITS-CVC","Infección del sitio de salida o túnel","Infección de FAV o injerto","Neumonía","Infección urinaria","Piel y tejidos blandos","Profilaxis","Otra"];
const RESIST=["Sensible","SAMR","BLEE","Carbapenemasa","Otro multirresistente","Sin antibiograma"];
