function dlgAud(){openDlg("Registrar auditoría",'<div class="form"><label class="f">Fecha<input type="date" id="au_f" value="'+iso(TODAY())+'"></label><label class="f" style="grid-column:span 2">Tipo<select id="au_t">'+opt(AUD_T,AUD_T[0])+'</select></label><label class="f">Oportunidades o ítems observados<input type="number" id="au_o"></label><label class="f">Cumplidos<input type="number" id="au_c"></label><label class="f">Observador<input type="text" id="au_b" value="'+esc(ST.user)+'"></label><label class="f wide">Nota<input type="text" id="au_n"></label></div>',"Registrar",()=>{if(needUser())return"Falta el usuario que registra.";const o=num($("au_o").value),c=num($("au_c").value),f=pdate($("au_f").value);if(!f||o==null||c==null||o<=0)return"Fecha, observados y cumplidos son obligatorios.";if(c>o)return"Los cumplidos no pueden superar los observados.";
  addRec("aud","AU-",{Fecha:f,Tipo:$("au_t").value,Observadas:o,Cumplidas:c,Observador:$("au_b").value.trim(),Nota:$("au_n").value.trim()});render();toast("Auditoría registrada.");});}

