/* ================= v0.2 · ultrafiltración de la sesión ================= */
/* UF neta por peso (kg ≈ L) y tasa de UF normalizada al peso post (mL/kg/h). */
function ufCalc(pre,post,min){if(pre==null||post==null)return null;const kg=pre-post;const ml=kg*1000;return{kg,ml,ufr:min&&post?ml/post/(min/60):null};}
function sesUF(s){const u=ufCalc(num(s.PesoPre),num(s.PesoPost),num(s.DuracionMin));if(!u)return null;return{kg:num(s.UFNeta)!=null?num(s.UFNeta):u.kg,ufr:num(s.UFR)!=null?num(s.UFR):u.ufr,maq:num(s.UFMaquina)};}
function ufView(p,r){const u=ufCalc(num(r.pp),num(r.pq),num(r.min));if(!u)return'<span class="sd">—</span>';const dry=num(p&&p.PesoSeco);const pq=num(r.pq);const over=dry!=null&&pq!=null?pq-dry:null;const m=num(r.ufm);
  return'<strong class="mono">'+f1(u.kg,1)+' L</strong>'+(u.ufr!=null?'<span class="sub" style="'+(u.ufr>13?"color:var(--bad);font-weight:700":"")+'" title="Tasa de ultrafiltración: UF en mL / peso post / horas">'+f1(u.ufr,1)+' mL/kg/h</span>':'')+
   (over!=null?'<span class="sub" title="Peso post menos peso seco">post − seco '+(over>0?"+":"")+f1(over,1)+' kg</span>':'')+(m!=null?'<span class="sub" title="UF de la máquina menos UF por peso: líquidos administrados o ingeridos en la sesión">máq. − peso '+(m-u.ml>0?"+":"")+Math.round(m-u.ml)+' mL</span>':'');}

/* ================= v0.2 · estudios, imágenes y procedimientos ambulatorios ================= */
const EST_TIPOS=["Imagen diagnóstica","Procedimiento","Examen especializado","Concepto de especialista"];
const EST_NOM=["Ecocardiograma","Electrocardiograma","Holter de 24 horas","Prueba de esfuerzo o perfusión miocárdica","Radiografía de tórax","Ecografía renal y de vías urinarias","Ecografía abdominal","Doppler de miembros superiores (mapeo vascular)","Doppler de la FAV","Fistulografía","Endoscopia digestiva alta","Colonoscopia","Densitometría ósea","Fondo de ojo","Mamografía","Citología cervicovaginal","Tomografía","Resonancia magnética","Biopsia","Valoración por cardiología","Valoración por cirugía vascular"];
function estRelevantes(p){return(p._est||[]).filter(e=>e.Relevante==="Sí").slice().reverse();}
function estVencidos(p,c){return(p._est||[]).filter(e=>e.ProximoControl&&e.ProximoControl<=c&&!(p._est||[]).some(x=>x!==e&&x.Nombre===e.Nombre&&x.Fecha>e.Fecha));}
function estForm(){const T=iso(TODAY());return'<div class="form"><label class="f">Fecha del estudio<input type="date" id="r_f" value="'+T+'"></label><label class="f">Tipo<select id="r_t">'+opt(EST_TIPOS,"Imagen diagnóstica")+'</select></label><label class="f" style="grid-column:span 2">Estudio o procedimiento<input type="text" id="r_x" list="r_xl" placeholder="p. ej. Ecocardiograma"><datalist id="r_xl">'+EST_NOM.map(x=>'<option value="'+esc(x)+'">').join("")+'</datalist></label><label class="f wide">Qué dice el reporte (hallazgos y conclusión)<textarea id="r_d" rows="3"></textarea></label><label class="f">¿Tener presente?<select id="r_rel">'+opt(["Sí","No"],"Sí")+'</select></label><label class="f" style="grid-column:span 2">Seguimiento indicado<input type="text" id="r_s" placeholder="p. ej. control con cardiología"></label><label class="f">Próximo control<input type="date" id="r_pc"></label><label class="f wide">Soporte (dónde está el reporte)<input type="text" id="r_so" placeholder="HC, carpeta, número de orden"></label></div><button type="button" class="btn" data-a="pregsave|est" style="margin-top:8px">Registrar estudio</button><p class="note">Lo marcado «tener presente» aparece arriba en la ficha, en la Valoración mensual y en el análisis para la HC. Para corregir un registro, anúlelo con motivo y regístrelo de nuevo.</p>';}
function estSave(p){const v=id=>($(id)||{}).value||"";const f=pdate(v("r_f")),x=v("r_x").trim(),d=v("r_d").trim();if(!f||!x){toast("Escriba la fecha y el estudio.");return false;}if(f>TODAY()){toast("La fecha del estudio no puede ser futura.");return false;}if(d.length<5){toast("Escriba qué dice el reporte.");return false;}
  addRec("est","ES-",{Paciente:p.ID,Fecha:f,Tipo:v("r_t"),Nombre:x,Resultado:d,Relevante:v("r_rel")||"No",Seguimiento:v("r_s").trim(),ProximoControl:pdate(v("r_pc")),Soporte:v("r_so").trim()});return true;}

/* ================= v0.2 · vacunación contra hepatitis B ================= */
/* Lógica según CDC 2001 (MMWR 50 RR-5), ACIP 2018 (MMWR Recomm Rep 67(1)) y el protocolo GSH-PT-001. El esquema exacto lo valida farmacia (pendiente del Anexo 1). */
function vacEsquemas(){const E=(ST.book&&ST.book.cfgv.vacEsq)||CFG_DEF.vacEsq;return E.filter(e=>e&&e.n&&Array.isArray(e.m)&&e.m.length);}
function vacMeses(nom){const e=vacEsquemas().find(x=>x.n===nom);return e?e.m:(vacEsquemas()[0]||{m:[0,1,2,6]}).m;}
function vacDoses(p,c){return(p._vac||[]).filter(v=>(v.Vacuna||"VHB")==="VHB"&&v.Fecha&&(!c||v.Fecha<=c)).slice().sort((a,b)=>a.Fecha-b.Fecha||String(a.ID).localeCompare(b.ID));}
function labTxt(l){return l?(EX[l.Examen]&&EX[l.Examen].txt?l.Valor:f1(num(l.Valor),0))+" · "+fd(l.FechaToma):"sin dato";}
function vacStatus(p,c){c=c||ST.corte;const D=vacDoses(p,c);const hb=lastLab(p,"HBsAg",null,c),ab=lastLab(p,"AntiHBc",null,c),as=lastLab(p,"AntiHBs",null,c);const asv=as?num(as.Valor):null;
  const o={D,hb,ab,as,next:null,lvl:"base",code:"",txt:"",accion:false};const R=(code,lvl,txt,extra)=>Object.assign(o,{code,lvl,txt,accion:["esq_venc","post_pend","nr1","resp_anual","resp_ref","susc","abc_ais","anti_sin_dosis","ficha"].includes(code)},extra||{});
  if(hb&&/^react/i.test(hb.Valor))return R("hbs","bad","HBsAg reactivo ("+fd(hb.FechaToma)+"): no vacunar; máquina, sala y personal dedicados (CDC 2001; GSH-PT-001).");
  const ser={};D.forEach(d=>{const k=d.Serie||"1";(ser[k]=ser[k]||[]).push(d);});const nums=Object.keys(ser).filter(k=>/^\d+$/.test(k)).map(Number).sort((a,b)=>a-b);
  o.series=nums.map(n=>{const L=ser[String(n)];const m=vacMeses(L[0].Esquema);return{n,L,m,k:L.length,comp:L.length>=m.length};});
  const ref=ser["Refuerzo"]||[];o.refuerzos=ref;
  if(!nums.length){
    if(ab&&/^react/i.test(ab.Valor)&&asv!=null&&asv>=10)return R("inm_inf","ok","Inmune por infección pasada (anti-HBc reactivo y anti-HBs "+f1(asv,0)+"): no requiere vacuna (CDC 2001).");
    if(ab&&/^react/i.test(ab.Valor))return R("abc_ais","warn","Anti-HBc reactivo con anti-HBs < 10 o sin dato: conducta según nefrología e infectología (protocolo GSH-PT-001).");
    if(asv!=null&&asv>=10)return R("anti_sin_dosis","warn","Anti-HBs "+f1(asv,0)+" sin dosis registradas: registre las dosis previas del carné o confirme el anti-HBc.");
    if(p.VacunaVHB&&p.VacunaVHB!=="No vacunado")return R("ficha","warn","Según la ficha: «"+p.VacunaVHB+"», sin dosis registradas en la herramienta. Registre las dosis del carné.");
    return R("susc","bad","Susceptible sin vacunar (anti-HBs "+(asv==null?"sin dato":f1(asv,0))+"): iniciar esquema de alta dosis.",{next:c});}
  const cur=o.series[o.series.length-1];const first=cur.L[0].Fecha,lastD=cur.L[cur.L.length-1].Fecha;o.cur=cur;
  if(!cur.comp){const k=cur.k;const anchor=addMonths(first,cur.m[k]);const minI=addMonths(lastD,cur.m[k]-cur.m[k-1]);const nx=anchor>minI?anchor:minI;
    return R(nx<=c?"esq_venc":"esq",nx<=c?"bad":"warn","Serie "+cur.n+": dosis "+k+" de "+cur.m.length+". Próxima dosis "+(nx<=c?"vencida desde ":"el ")+fd(nx)+".",{next:nx});}
  const post=(p._lab.AntiHBs||[]).filter(l=>l.FechaToma>addDays(lastD,27)&&l.FechaToma<=c);const desde=addDays(lastD,30),hasta=addMonths(lastD,2);
  if(!post.length){if(c<desde)return R("post_esp","info","Serie "+cur.n+" completa ("+fd(lastD)+"). Anti-HBs de control entre "+fd(desde)+" y "+fd(hasta)+" (1-2 meses después de la última dosis).",{next:desde});
    return R("post_pend","warn","Serie "+cur.n+" completa ("+fd(lastD)+") sin anti-HBs de control: tomarlo ya (debía entre "+fd(desde)+" y "+fd(hasta)+").",{next:desde});}
  const pv=num(post[0].Valor);
  if(pv==null||pv<10){if(cur.n<2)return R("nr1","bad","Sin respuesta a la serie "+cur.n+" (anti-HBs "+(pv==null?"?":f1(pv,0))+" el "+fd(post[0].FechaToma)+"): revacunar con una serie completa (CDC 2001; ACIP 2018).",{next:c});
    return R("nr2","info","No respondedor después de "+cur.n+" series: no más vacunas; HBsAg mensual (CDC 2001).");}
  const lastA=(p._lab.AntiHBs||[]).filter(l=>l.FechaToma<=c).slice(-1)[0];const la=num(lastA.Valor);const refAfter=ref.filter(r=>r.Fecha>=lastA.FechaToma);
  if(la!=null&&la<10&&!refAfter.length)return R("resp_ref","warn","Respondedor con anti-HBs "+f1(la,0)+" el "+fd(lastA.FechaToma)+": aplicar dosis de refuerzo (CDC 2001).",{next:c});
  const nxt=addMonths(lastA.FechaToma,12);if(nxt<=c)return R("resp_anual","warn","Respondedor (anti-HBs "+f1(pv,0)+" posvacunación). Anti-HBs anual vencido desde "+fd(nxt)+".",{next:nxt});
  return R("resp","ok","Respondedor (anti-HBs "+f1(pv,0)+" el "+fd(post[0].FechaToma)+"). Próximo anti-HBs anual: "+fd(nxt)+(refAfter.length?" · refuerzo "+fd(refAfter[refAfter.length-1].Fecha):"")+".",{next:nxt});}
const VAC_GRUPOS=[["accion","Requieren acción"],["esq","En esquema"],["prot","Protegidos"],["hbs","HBsAg reactivo"],["nr","No respondedores"],["all","Todos"]];
function vacGrupo(s){return s.accion?"accion":s.code==="esq"||s.code==="post_esp"?"esq":["resp","inm_inf"].includes(s.code)?"prot":s.code==="hbs"?"hbs":s.code==="nr2"?"nr":"otro";}
function vacNextDefaults(p){const D=vacDoses(p,null);const s=vacStatus(p,TODAY());let serie="1";if(s.code==="nr1")serie=String((s.cur?s.cur.n:1)+1);else if(s.code==="resp_ref")serie="Refuerzo";else if(s.cur&&!s.cur.comp)serie=String(s.cur.n);
  const esq=serie==="Refuerzo"?"":(s.cur&&String(s.cur.n)===serie?s.cur.L[0].Esquema:(vacEsquemas()[0]||{}).n);const n=serie==="Refuerzo"?1:D.filter(d=>(d.Serie||"1")===serie).length+1;return{serie,esq,n};}
function dlgVac(pid){const p=IDX.pac.get(pid);const df=vacNextDefaults(p);const s=vacStatus(p,TODAY());
  openDlg("Registrar dosis de vacuna VHB · "+pid+" · "+nombre(p),'<p class="note">Estado actual: '+esc(s.txt)+'</p><div class="form"><label class="f">Fecha de aplicación<input type="date" id="vc_f" value="'+iso(TODAY())+'"></label><label class="f">Serie<select id="vc_s">'+opt([["1","1.ª serie"],["2","2.ª serie (revacunación)"],["3","3.ª serie"],["Refuerzo","Refuerzo"]],df.serie)+'</select></label><label class="f">Dosis n.º<input type="number" id="vc_n" min="1" max="6" value="'+df.n+'"></label><label class="f wide">Esquema<select id="vc_e">'+opt(vacEsquemas().map(e=>e.n),df.esq||"","—")+'</select></label><label class="f">Lote<input type="text" id="vc_l"></label><label class="f wide">Observación<input type="text" id="vc_o" placeholder="Reacción, quién aplicó, carné"></label></div><p class="note">Los esquemas se editan en Referencia y deben coincidir con el protocolo GSH-PT-001 validado por farmacia.</p>',"Registrar dosis",()=>{
    if(needUser())return"Falta el usuario que registra.";const f=pdate($("vc_f").value);if(!f)return"Fecha inválida.";if(f>TODAY())return"La fecha no puede ser futura.";const serie=$("vc_s").value,n=num($("vc_n").value),esq=$("vc_e").value;
    if(serie!=="Refuerzo"&&!esq)return"Elija el esquema.";if(!n||n<1)return"Número de dosis inválido.";
    const prev=vacDoses(p,null).filter(d=>(d.Serie||"1")===serie);if(prev.some(d=>num(d.NumDosis)===n))return"Ya hay una dosis "+n+" en esa serie. Anule la anterior si está errada.";if(prev.length&&f<prev[prev.length-1].Fecha)return"La fecha es anterior a la última dosis de la serie.";
    addRec("vac","VC-",{Paciente:pid,Vacuna:"VHB",Esquema:serie==="Refuerzo"?"Refuerzo":esq,Serie:serie,NumDosis:n,Fecha:f,Lote:$("vc_l").value.trim(),Observacion:$("vc_o").value.trim()});reindex();vacSync(IDX.pac.get(pid));reindex();render();toast("Dosis registrada.");});}
/* mantiene coherentes los campos que usa la matriz CAC (var 54) */
function vacSync(p){if(!p)return;const s=vacStatus(p,TODAY());const ch={};if(s.series&&s.series.length){ch.VacunaVHB=s.series.some(x=>x.comp)?"Esquema completo":"Esquema incompleto";}
  if(s.code==="nr2")ch.VHBNoRespondedor="SI";else if(["resp","resp_anual","resp_ref"].includes(s.code))ch.VHBNoRespondedor="NO";if(Object.keys(ch).length)updRec("pac",p,ch);}
function vVac(){ensureIdx();const c=ST.corte;const f=ST.ui.vacf||"accion";const R=ST.book.pac.filter(p=>epsOk(p)&&activeAt(p,c)).map(p=>({p,s:vacStatus(p,c)}));R.forEach(r=>r.g=vacGrupo(r.s));
  const n=g=>g==="all"?R.length:R.filter(r=>r.g===g).length;const R2=(f==="all"?R:R.filter(r=>r.g===f)).sort((a,b)=>(a.s.next||new Date(9e15))-(b.s.next||new Date(9e15)));
  let h=head("Vacunación contra hepatitis B","Dosis aplicadas, próxima dosis y estado según los resultados de HBsAg, anti-HBc y anti-HBs que llegan a Paraclínicos. Calculado al "+fd(c)+".",'<button type="button" class="btn" data-a="vacexp">Exportar a Excel</button>');
  h+='<div class="tiles">'+[["accion","bad"],["esq","warn"],["prot","ok"],["nr","base"],["hbs","bad"]].map(([g,cl])=>'<div class="tile '+cl+'"><span class="tv">'+n(g)+'</span><span class="tl">'+esc(VAC_GRUPOS.find(x=>x[0]===g)[1].toLowerCase())+'</span></div>').join("")+'</div>';
  h+='<details class="panel hist"><summary>Cómo se define el estado</summary><ul class="note"><li>HBsAg reactivo: infección; no se vacuna y se dializa en máquina, sala y personal dedicados.</li><li>Anti-HBc y anti-HBs reactivos sin vacuna: inmunidad por infección pasada.</li><li>Susceptible: anti-HBs &lt; 10 mUI/mL sin dosis registradas. Se vacuna con dosis alta (40 µg) y se toma HBsAg mensual mientras sea susceptible.</li><li>Serie completa: anti-HBs de control 1 a 2 meses después de la última dosis. ≥ 10 = respondedor; &lt; 10 = segunda serie completa; si tampoco responde, no respondedor (HBsAg mensual).</li><li>Respondedor: anti-HBs anual y refuerzo si baja de 10.</li></ul><p class="note">Fuentes: CDC, MMWR 2001;50(RR-5); ACIP, MMWR Recomm Rep 2018;67(1); protocolo GSH-PT-001 (su esquema de vacunación está pendiente de validación por farmacia y el algoritmo del Anexo 1 aún no se ha incorporado).</p></details>';
  h+='<div class="seg" role="group">'+VAC_GRUPOS.map(([k,l])=>'<button type="button" data-a="vacf|'+k+'" aria-pressed="'+(f===k)+'">'+l+' ('+n(k)+')</button>').join("")+'</div>';
  h+='<div class="panel tablebox" style="padding:0"><table><thead><tr><th>Paciente</th><th>Estado y conducta</th><th>Dosis</th><th>HBsAg</th><th>Anti-HBc</th><th>Anti-HBs</th><th>Próximo paso</th><th></th></tr></thead><tbody>'+
   (R2.map(({p,s})=>'<tr><td><strong>'+esc(p.ID)+'</strong><span class="sub">'+esc(nombre(p))+' · '+esc(p.Turno||"")+'</span></td><td style="font-size:13px;min-width:260px"><span class="st '+s.lvl+'">'+esc(vacEtiqueta(s.code))+'</span> '+esc(s.txt)+'</td><td style="font-size:12.5px">'+(s.series&&s.series.length?s.series.map(x=>'Serie '+x.n+': '+x.k+'/'+x.m.length+'<span class="sub">'+x.L.map(d=>fd(d.Fecha)).join(", ")+'</span>').join("")+(s.refuerzos&&s.refuerzos.length?'Refuerzo: '+s.refuerzos.map(d=>fd(d.Fecha)).join(", "):""):'<span class="sd">sin dosis</span>')+'</td><td style="font-size:12.5px">'+esc(labTxt(s.hb))+'</td><td style="font-size:12.5px">'+esc(labTxt(s.ab))+'</td><td style="font-size:12.5px">'+esc(labTxt(s.as))+'</td><td class="mono" style="'+(s.next&&s.next<=c&&s.accion?"color:var(--bad);font-weight:700":"")+'">'+(s.next?fd(s.next):"—")+'</td><td>'+(s.code!=="hbs"&&s.code!=="nr2"&&s.code!=="inm_inf"?'<button type="button" class="btn sm primary" data-a="vacnew|'+p.ID+'">Registrar dosis</button>':'')+'</td></tr>').join("")||'<tr><td colspan="8" class="empty">Nadie en este grupo.</td></tr>')+'</tbody></table></div>';
  h+='<p class="note">El anti-HBs, el HBsAg y el anti-HBc se registran en Paraclínicos o los carga Laboratorio; el estado se recalcula solo. Las dosis registradas actualizan los campos de vacunación de la ficha que usa la matriz CAC.</p>';return h;}
function vacEtiqueta(c){return({hbs:"HBsAg +",inm_inf:"Inmune",resp:"Respondedor",resp_anual:"Anti-HBs anual",resp_ref:"Refuerzo",esq:"En esquema",esq_venc:"Dosis vencida",post_esp:"Esperar control",post_pend:"Control pendiente",nr1:"Revacunar",nr2:"No respondedor",abc_ais:"Anti-HBc aislado",anti_sin_dosis:"Sin dosis",ficha:"Sin dosis",susc:"Susceptible"})[c]||c;}
function vacExport(){ensureIdx();const c=ST.corte;const R=ST.book.pac.filter(p=>epsOk(p)&&activeAt(p,c)).map(p=>({p,s:vacStatus(p,c)}));
  exportSheets("Vacunacion_VHB_"+iso(c)+".xlsx",[["Estado por paciente",R,PID_COLS.map(x=>[x[0],r=>x[1](r.p)]).concat([["Turno",r=>r.p.Turno],["Estado",r=>vacEtiqueta(r.s.code)],["Detalle",r=>r.s.txt],["Próximo paso",r=>r.s.next],["HBsAg",r=>labTxt(r.s.hb)],["Anti-HBc",r=>labTxt(r.s.ab)],["Anti-HBs",r=>labTxt(r.s.as)],["Dosis registradas",r=>r.s.D.length]])],
   ["Dosis",ST.book.vac.filter(live).sort((a,b)=>a.Fecha-b.Fecha),[["ID",v=>v.ID],["Paciente",v=>v.Paciente],["Nombre",v=>nombre(IDX.pac.get(v.Paciente))],["Serie",v=>v.Serie],["Dosis",v=>v.NumDosis],["Esquema",v=>v.Esquema],["Fecha",v=>v.Fecha],["Lote",v=>v.Lote],["Observación",v=>v.Observacion],["Registró",v=>v.Usuario]]]]);}

/* ================= v0.2 · trasplante: estado del proceso y lo que falta ================= */
const TX_EST=["Pendiente","Solicitado","Realizado","No aplica"];
function txItems(){return((ST.book&&ST.book.cfgv.txItems)||CFG_DEF.txItems).filter(Boolean);}
function txState(p){const last={};(p._txs||[]).forEach(r=>{last[r.Item]=r;});const items=txItems().map(it=>({it,r:last[it]||null,e:last[it]?last[it].Estado:"Pendiente"}));
  const hecho=items.filter(x=>x.e==="Realizado").length,na=items.filter(x=>x.e==="No aplica").length,sol=items.filter(x=>x.e==="Solicitado").length;const falta=items.filter(x=>x.e!=="Realizado"&&x.e!=="No aplica");
  const ult=(p._txs||[]).slice(-1)[0]||null;return{items,hecho,na,sol,apl:items.length-na,falta,ult};}
const TX_EN_PROCESO=["Idóneo, en estudio","En lista de espera"];
function vTx(){ensureIdx();const c=ST.corte;const f=ST.ui.txf||"proc";const act=ST.book.pac.filter(p=>epsOk(p)&&activeAt(p,c));const R=act.map(p=>({p,t:txState(p)}));
  const filt={proc:r=>TX_EN_PROCESO.includes(r.p.TxEstado),sin:r=>!r.p.TxEstado||r.p.TxEstado==="Sin evaluar",exc:r=>["No idóneo (contraindicación con soporte)","Disentimiento","Cuidados paliativos"].includes(r.p.TxEstado),all:()=>true};const R2=R.filter(filt[f]||filt.all);
  let h=head("Trasplante renal","Estado del proceso de cada paciente y estudios que le faltan. El estado (Sin evaluar, Idóneo en estudio, En lista de espera…) alimenta el indicador dia_21 y la matriz CAC; la lista de estudios es la guía de seguimiento.",'<button type="button" class="btn" data-a="txexp">Exportar a Excel</button>');
  h+='<div class="tiles">'+TX.map(t=>{const k=act.filter(p=>(p.TxEstado||"Sin evaluar")===t).length;return'<div class="tile '+(t==="Sin evaluar"?(k?"warn":"ok"):t==="En lista de espera"?"ok":"base")+'"><span class="tv">'+k+'</span><span class="tl">'+esc(t.toLowerCase())+'</span></div>';}).join("")+'</div>';
  h+='<div class="seg" role="group">'+[["proc","En proceso"],["sin","Sin evaluar"],["exc","Excluidos"],["all","Todos"]].map(([k,l])=>'<button type="button" data-a="txf|'+k+'" aria-pressed="'+(f===k)+'">'+l+' ('+R.filter(filt[k]).length+')</button>').join("")+'</div>';
  const sel=ST.ui.txp&&IDX.pac.get(ST.ui.txp)?ST.ui.txp:null;
  h+='<div class="pacgrid"><div class="panel tablebox" style="padding:0"><table><thead><tr><th>Paciente</th><th>Estado</th><th class="num">Avance</th><th>Falta</th></tr></thead><tbody>'+(R2.map(({p,t})=>'<tr class="click'+(sel===p.ID?" sel":"")+'" data-a="txsel|'+p.ID+'"><td><strong>'+esc(p.ID)+'</strong><span class="sub">'+esc(nombre(p))+'</span></td><td style="font-size:13px">'+esc(p.TxEstado||"Sin evaluar")+(p.TxFecha?'<span class="sub">'+fd(p.TxFecha)+'</span>':'')+'</td><td class="num">'+t.hecho+'/'+t.apl+'<span class="bar"><span style="width:'+(t.apl?t.hecho/t.apl*100:0)+'%"></span></span></td><td style="font-size:12.5px">'+(t.falta.length?esc(t.falta.slice(0,3).map(x=>x.it.split(" · ").pop()).join("; "))+(t.falta.length>3?' <span class="sub">y '+(t.falta.length-3)+' más</span>':''):'<span class="st ok">Completo</span>')+'</td></tr>').join("")||'<tr><td colspan="4" class="empty">Nadie en este grupo.</td></tr>')+'</tbody></table></div>';
  h+='<div class="panel" style="display:grid;gap:10px;min-width:0">'+(sel?txDetail(IDX.pac.get(sel)):'<div class="empty">Elija un paciente para ver y actualizar su proceso.</div>')+'</div></div>';
  h+='<p class="note">Lista de estudios basada en KDIGO 2020 para candidatos a trasplante (resumen: Chadban SJ, et al. Transplantation 2020;104(4):708-714). La valoración odontológica y la urológica dependen del protocolo de la IPS trasplantadora. La lista se edita en Referencia y debe validarse con la IPS a la que se remite.</p>';return h;}
function txDetail(p){const t=txState(p);const G={};t.items.forEach(x=>{const g=x.it.split(" · ")[0];(G[g]=G[g]||[]).push(x);});
  let h='<div class="mhead"><div><h3 style="margin:0">'+esc(p.ID)+' · '+esc(nombre(p))+'</h3><p class="note" style="margin:2px 0 0">'+t.hecho+' de '+t.apl+' estudios realizados · '+t.sol+' solicitados'+(t.ult?' · última actualización '+fd(t.ult.Fecha)+' por '+esc(t.ult.Usuario||""):'')+'</p></div><button type="button" class="btn primary" data-a="txsave|'+p.ID+'">Guardar cambios</button></div>';
  h+='<div class="form"><label class="f">Estado (CAC var 62)<select id="tx_e">'+opt(TX,p.TxEstado||"Sin evaluar")+'</select></label><label class="f">Fecha del concepto o de ingreso a lista<input type="date" id="tx_f" value="'+(p.TxFecha?iso(p.TxFecha):"")+'"></label><label class="f">IPS de lista de espera (código REPS)<input type="text" id="tx_i" value="'+esc(p.TxIPS||"")+'"></label></div>';
  Object.entries(G).forEach(([g,L])=>{h+='<div style="min-width:0"><h3>'+esc(g)+'</h3><div class="tablebox"><table class="mini"><tbody>'+L.map(x=>{const i=t.items.indexOf(x);return'<tr><td style="min-width:200px">'+esc(x.it.split(" · ").slice(1).join(" · "))+(x.r&&x.r.Resultado?'<span class="sub">'+esc(x.r.Resultado)+'</span>':'')+'</td><td><select data-txi="'+i+'|e" style="min-width:118px">'+opt(TX_EST,x.e)+'</select></td><td><input type="date" data-txi="'+i+'|f" value="'+(x.r&&x.r.Fecha?iso(x.r.Fecha):"")+'" style="width:140px"></td><td><input type="text" data-txi="'+i+'|r" value="" placeholder="'+(x.r&&x.r.Resultado?"Actualizar resultado":"Resultado o nota")+'" style="min-width:150px"></td></tr>';}).join("")+'</tbody></table></div></div>';});
  const H=(p._txs||[]).slice().reverse().slice(0,15);if(H.length)h+='<details class="hist" style="min-width:0"><summary>Trazabilidad ('+(p._txs||[]).length+' registros)</summary><div class="tablebox"><table class="mini"><tbody>'+H.map(r=>'<tr><td class="mono">'+fd(r.Fecha)+'</td><td>'+esc(r.Item)+'</td><td>'+esc(r.Estado)+(r.Resultado?'<span class="sub">'+esc(r.Resultado)+'</span>':'')+'</td><td><span class="sub">'+esc(r.Usuario||"")+' · '+esc(r.Registrado||"")+'</span></td></tr>').join("")+'</tbody></table></div></details>';
  return h;}
function txSave(pid){if(needUser())return;const p=IDX.pac.get(pid);const t=txState(p);let n=0;const errs=[];
  t.items.forEach((x,i)=>{const g=k=>{const el=document.querySelector('[data-txi="'+i+'|'+k+'"]');return el?el.value.trim():"";};const e=g("e"),f=pdate(g("f")),r=g("r");
    const prevF=x.r&&x.r.Fecha?iso(x.r.Fecha):"";if(e===x.e&&!r&&(f?iso(f):"")===prevF)return;if(f&&f>TODAY()){errs.push(x.it);return;}
    addRec("txs","TX-",{Paciente:pid,Item:x.it,Estado:e,Fecha:f||TODAY(),Resultado:r||(x.r?x.r.Resultado:"")});n++;});
  const ch={TxEstado:$("tx_e").value,TxFecha:pdate($("tx_f").value),TxIPS:$("tx_i").value.trim()||null};
  const ins=txItems().find(it=>/Inscripción en lista de espera/.test(it));if(ins){const el=document.querySelector('[data-txi="'+txItems().indexOf(ins)+'|e"]');if(el&&el.value==="Realizado"&&!["En lista de espera","Trasplantado"].includes(ch.TxEstado)){ch.TxEstado="En lista de espera";if(!ch.TxFecha){const fe=document.querySelector('[data-txi="'+txItems().indexOf(ins)+'|f"]');ch.TxFecha=pdate(fe&&fe.value)||TODAY();}}}
  const m=updRec("pac",p,ch);if(errs.length){toast("Fechas futuras en: "+errs.slice(0,2).join("; ")+". Lo demás se guardó.");}reindex();render();if(!errs.length)toast(n||m?"Proceso de trasplante actualizado ("+n+" estudios"+(m?", estado":"")+").":"Sin cambios.");}
function txExport(){ensureIdx();const c=ST.corte;const P=ST.book.pac.filter(p=>epsOk(p)&&activeAt(p,c));
  exportSheets("Trasplante_"+iso(c)+".xlsx",[["Proceso por paciente",P,PID_COLS.concat([["Estado",p=>p.TxEstado||"Sin evaluar"],["Fecha",p=>p.TxFecha],["IPS",p=>p.TxIPS],["Realizados",p=>txState(p).hecho],["Aplicables",p=>txState(p).apl],["Faltan",p=>txState(p).falta.map(x=>x.it).join("; ")]])],
   ["Trazabilidad",ST.book.txs.filter(live).sort((a,b)=>a.Fecha-b.Fecha),[["ID",r=>r.ID],["Paciente",r=>r.Paciente],["Nombre",r=>nombre(IDX.pac.get(r.Paciente))],["Ítem",r=>r.Item],["Estado",r=>r.Estado],["Fecha",r=>r.Fecha],["Resultado",r=>r.Resultado],["Registró",r=>r.Usuario],["Registrado",r=>r.Registrado]]]]);}

/* ================= v0.2 · lo que hay que tener presente del paciente ================= */
function tenerPresente(p,c){c=c||ST.corte;const o=[];estRelevantes(p).forEach(e=>o.push({lvl:"info",t:e.Nombre+" ("+fd(e.Fecha)+")",d:e.Resultado+(e.Seguimiento?" · Seguimiento: "+e.Seguimiento:"")+(e.ProximoControl?" · Próximo control "+fd(e.ProximoControl):""),id:e.ID,venc:e.ProximoControl&&e.ProximoControl<=c}));
  const v=vacStatus(p,c);if(v.lvl!=="ok"&&v.code!=="nr2")o.push({lvl:v.lvl==="bad"?"bad":"warn",t:"Vacunación VHB",d:v.txt});else if(v.code==="nr2")o.push({lvl:"info",t:"Vacunación VHB",d:v.txt});
  if(TX_EN_PROCESO.includes(p.TxEstado)){const t=txState(p);if(t.falta.length)o.push({lvl:"info",t:"Trasplante · "+p.TxEstado,d:"Faltan "+t.falta.length+": "+t.falta.slice(0,4).map(x=>x.it.split(" · ").pop()).join("; ")+(t.falta.length>4?"…":"")});}
  return o;}
function tpHtml(p,c,withBtn){const L=tenerPresente(p,c);if(!L.length)return"";return'<div class="alert info"><p><strong>Tener presente</strong></p><ul style="margin:4px 0 0;padding-left:18px;font-size:13.5px">'+L.map(x=>'<li><strong'+(x.lvl==="bad"?' style="color:var(--bad)"':'')+'>'+esc(x.t)+'</strong>: '+esc(x.d)+(x.venc?' <span class="st bad">control vencido</span>':'')+(withBtn&&x.id?' <button type="button" class="lnk" data-a="estrel|'+x.id+'">quitar de aquí</button>':'')+'</li>').join("")+'</ul></div>';}

/* ================= v0.2 · solicitud de laboratorio del mes (compartida con el módulo Laboratorio) ================= */
const SOL_EST=["Pendiente","Muestra tomada","No tomada"];
function solMes(ctx){return ctx==="lab"?(ST.ui.solmesL||ym(TODAY())):(ST.ui.solmes||ym(addMonths(monthStart(ST.corte),1)));}
function solRecs(mes,prog){prog=prog||"hd";return ST.book.sol.filter(live).filter(r=>r.Mes===mes&&(r.Programa||"hd")===prog);}
function solPropuesta(mes){ensureIdx();const[y,mm]=mes.split("-").map(Number);const ms=new Date(y,mm-1,1);const ref=ST.corte>ms?ST.corte:ms;
  return ST.book.pac.filter(p=>activeAt(p,ST.corte)||activeAt(p,ms)).sort((a,b)=>String(a.ID).localeCompare(b.ID)).map(p=>{const ex=examsForMonth(p,y,mm).map(e=>({k:e.k,why:e.why}));labDue(p,ST.corte).filter(v=>v.st==="vencido"&&!ex.some(e=>e.k===v.k)).forEach(v=>ex.push({k:v.k,why:"Vencido"}));const NO_LAB=["EscalaCV","EKG","TAS","KtV","URR"];return{p,ex:ex.filter(e=>!NO_LAB.includes(e.k))};}).filter(x=>x.ex.length);}
function solResult(pid,k,mes){const p=IDX.pac.get(pid);if(!p)return null;const ms=pdate(mes+"-01"),me=monthEnd(ms);const L=(p._lab[k]||[]).filter(l=>l.FechaToma>=ms&&l.FechaToma<=me);return L.length?L[L.length-1]:null;}
function solGenerar(mes,soloNuevos){if(needUser())return;const P=solPropuesta(mes);const ya=new Set(solRecs(mes).map(r=>r.Paciente+"|"+r.Examen));let mx=0;ST.book.sol.forEach(o=>{const m=/(\d+)$/.exec(o.ID||"");if(m)mx=Math.max(mx,+m[1]);});const ts=nowTs();let n=0;
  P.forEach(({p,ex})=>ex.forEach(e=>{if(ya.has(p.ID+"|"+e.k))return;mx++;n++;ST.book.sol.push({ID:"SL-"+String(mx).padStart(6,"0"),Mes:mes,Programa:"hd",Paciente:p.ID,Examen:e.k,Origen:soloNuevos?"Calendario (agregado después)":e.why,Motivo:"",Estado:"Pendiente",FechaToma:null,Nota:"",Usuario:ST.user,Registrado:ts});}));
  if(n){logW(soloNuevos?"AGREGA":"GENERA","sol",mes,n+" exámenes de la solicitud de "+mes);changed();}reindex();render();toast(n?(soloNuevos?n+" exámenes agregados desde el calendario.":"Solicitud de "+mes+" generada: "+n+" exámenes."):"No hay nada nuevo que agregar.");}
function solView(ctx){ensureIdx();const mes=solMes(ctx);const R=solRecs(mes);const gen=R.length>0;const[y,mm]=mes.split("-").map(Number);const MT=["enero","febrero","marzo","abril","mayo","junio","julio","agosto","septiembre","octubre","noviembre","diciembre"][mm-1]+" de "+y;
  let h='<div class="panel" style="display:grid;gap:10px"><div class="mhead"><div><h3 style="margin:0">Solicitud de laboratorio · hemodiálisis · '+MT+'</h3><p class="note" style="margin:3px 0 0">'+(ctx==="lab"?"La genera el calendario institucional de Hemodiálisis; Laboratorio la valida, marca las muestras tomadas y carga los resultados. Cada corrección queda con usuario, fecha y motivo.":"Es la misma solicitud que ve Laboratorio. Calendario institucional: mensuales cada mes, trimestrales desde enero, semestrales en octubre y abril, anuales en abril, paquete de ingreso, HBsAg mensual en susceptibles y vencidos.")+'</p></div><div class="copyrow"><label class="f" style="min-width:160px">Mes<input type="month" id="'+(ctx==="lab"?"solmesL":"solmes")+'" value="'+mes+'"></label>'+(gen?'<button type="button" class="btn" data-a="soladd|'+mes+'">Agregar examen</button><button type="button" class="btn" data-a="solnew|'+mes+'">Traer lo nuevo del calendario</button>':'<button type="button" class="btn primary" data-a="solgen|'+mes+'">Generar solicitud de '+MT+'</button>')+'<button type="button" class="btn'+(gen?" primary":"")+'" data-a="solexp|'+mes+'">Exportar para laboratorio</button></div></div>';
  if(!gen){const P=solPropuesta(mes);const tot={};P.forEach(x=>x.ex.forEach(e=>{tot[e.k]=(tot[e.k]||0)+1;}));
    h+='<div class="alert warn"><p>Propuesta sin generar: al generarla queda fija para el mes y desde ahí cada cambio se registra. '+P.length+' pacientes · '+P.reduce((a,x)=>a+x.ex.length,0)+' exámenes.</p></div><div class="copyrow" style="gap:6px">'+Object.entries(tot).map(([k,n])=>'<span class="tag">'+esc(EX[k].l)+' · '+n+'</span>').join("")+'</div>';
    h+='<div class="tablebox"><table><thead><tr><th>Paciente</th><th>Turno</th><th>Exámenes propuestos</th></tr></thead><tbody>'+P.map(x=>'<tr><td><strong>'+esc(x.p.ID)+'</strong><span class="sub">'+esc(nombre(x.p))+' · '+esc(x.p.EPS||"")+'</span></td><td>'+esc(x.p.Turno||"—")+'</td><td><div class="copyrow" style="gap:4px">'+x.ex.map(e=>'<span class="st '+(e.why==="Vencido"?"bad":/ingreso|susceptible/i.test(e.why)?"warn":"base")+'" title="'+esc(e.why)+'">'+esc(EX[e.k].l)+'</span>').join("")+'</div></td></tr>').join("")+'</tbody></table></div></div>';return h;}
  const st=r=>{const res=solResult(r.Paciente,r.Examen==="BUNpre"||r.Examen==="BUNpost"?r.Examen:r.Examen,mes);return res?"Con resultado":r.Estado;};
  const cnt={};R.forEach(r=>{const s=st(r);cnt[s]=(cnt[s]||0)+1;});const by={};R.forEach(r=>{(by[r.Paciente]=by[r.Paciente]||[]).push(r);});
  h+='<div class="tiles mini-tiles"><div class="tile"><span class="tv">'+R.length+'</span><span class="tl">exámenes solicitados · '+Object.keys(by).length+' pacientes</span></div><div class="tile ok"><span class="tv">'+(cnt["Con resultado"]||0)+'</span><span class="tl">con resultado</span></div><div class="tile warn"><span class="tv">'+(cnt["Muestra tomada"]||0)+'</span><span class="tl">muestra tomada, sin resultado</span></div><div class="tile base"><span class="tv">'+(cnt.Pendiente||0)+'</span><span class="tl">pendientes</span></div><div class="tile bad"><span class="tv">'+(cnt["No tomada"]||0)+'</span><span class="tl">no tomadas</span></div></div>';
  const cls={"Con resultado":"ok","Muestra tomada":"warn","Pendiente":"base","No tomada":"bad"};
  h+='<div class="tablebox"><table><thead><tr><th>Paciente</th><th>Exámenes (clic para corregir)</th><th>Muestra</th></tr></thead><tbody>'+Object.entries(by).sort((a,b)=>a[0].localeCompare(b[0])).map(([pid,L])=>{const p=IDX.pac.get(pid);const pend=L.some(r=>r.Estado==="Pendiente"&&!solResult(pid,r.Examen,mes));const ft=L.map(r=>r.FechaToma).filter(Boolean).sort((a,b)=>b-a)[0];
    return'<tr><td><strong>'+esc(pid)+'</strong><span class="sub">'+esc(nombre(p))+' · '+esc(p?p.Turno||"":"")+'</span></td><td><div class="copyrow" style="gap:4px">'+L.map(r=>{const s=st(r);return'<button type="button" class="st '+cls[s]+'" style="background:none;cursor:pointer;font:inherit;font-size:11.5px;font-weight:700" data-a="solchip|'+r.ID+'" title="'+esc(s+" · "+(r.Origen||"")+(r.Motivo?" · "+r.Motivo:""))+'">'+esc(EX[r.Examen]?EX[r.Examen].l:r.Examen)+(r.Origen&&/agregado/i.test(r.Origen)?" +":"")+'</button>';}).join("")+'</div></td><td>'+(pend?'<button type="button" class="btn sm" data-a="soltom|'+pid+'|'+mes+'">Muestra tomada</button>':'')+(ft?'<span class="sub">'+fd(ft)+'</span>':'')+'</td></tr>';}).join("")+'</tbody></table></div>';
  const an=ST.book.sol.filter(r=>r.Mes===mes&&r.Anulado==="SI");if(an.length)h+='<details class="hist"><summary>Retirados de la solicitud ('+an.length+')</summary><ul class="note">'+an.map(r=>'<li>'+esc(r.Paciente)+' · '+esc(EX[r.Examen]?EX[r.Examen].l:r.Examen)+' · '+esc(r.MotivoAnulacion||"")+'</li>').join("")+'</ul></details>';
  return h+'<p class="note">Verde: con resultado cargado en el mes. Ámbar: muestra tomada sin resultado. Gris: pendiente. Rojo: no tomada (con motivo). «+»: agregado después de generar.</p></div>';}
function dlgSolChip(id){const r=ST.book.sol.find(x=>x.ID===id);const p=IDX.pac.get(r.Paciente);const res=solResult(r.Paciente,r.Examen,r.Mes);
  openDlg("Corregir solicitud · "+r.Paciente+" · "+(EX[r.Examen]?EX[r.Examen].l:r.Examen),'<p class="note">'+esc(nombre(p))+' · origen: '+esc(r.Origen||"")+(res?' · resultado '+esc(String(res.Valor))+' del '+fd(res.FechaToma):'')+'</p><div class="form"><label class="f">Acción<select id="sc_a">'+opt([["est","Cambiar estado"],["quitar","Retirar de la solicitud"]],"est")+'</select></label><label class="f">Estado<select id="sc_e">'+opt(SOL_EST,r.Estado)+'</select></label><label class="f">Fecha de toma<input type="date" id="sc_f" value="'+(r.FechaToma?iso(r.FechaToma):"")+'"></label><label class="f wide">Motivo (obligatorio para retirar o «no tomada»)<input type="text" id="sc_m" value="'+esc(r.Motivo||"")+'"></label></div>',"Guardar",()=>{
    if(needUser())return"Falta el usuario que registra.";const a=$("sc_a").value,m=$("sc_m").value.trim();
    if(a==="quitar"){if(m.length<4)return"Escriba el motivo para retirarlo.";anular("sol",id,m);reindex();render();toast("Examen retirado de la solicitud; queda en la bitácora.");return;}
    const e=$("sc_e").value,f=pdate($("sc_f").value);if(e==="No tomada"&&m.length<4)return"Escriba el motivo por el que no se tomó.";if(f&&f>TODAY())return"La fecha de toma no puede ser futura.";
    updRec("sol",r,{Estado:e,FechaToma:e==="Pendiente"?null:(f||r.FechaToma||(e==="Muestra tomada"?TODAY():null)),Motivo:m});reindex();render();toast("Solicitud corregida.");});}
function dlgSolAdd(mes){const P=ST.book.pac.filter(p=>activeAt(p,ST.corte)).sort((a,b)=>String(a.ID).localeCompare(b.ID));
  openDlg("Agregar examen a la solicitud de "+mes,'<div class="form"><label class="f wide">Paciente<select id="sa_p">'+opt(P.map(p=>[p.ID,p.ID+" · "+nombre(p)]),"","Seleccione…")+'</select></label><label class="f wide">Examen<select id="sa_x">'+opt(EXAMS.filter(e=>!["KtV","URR","TAS","EscalaCV"].includes(e.k)).map(e=>[e.k,e.l]),"","Seleccione…")+'</select></label><label class="f wide">Motivo (validación o corrección)<input type="text" id="sa_m" placeholder="p. ej. control de potasio por hiperpotasemia"></label></div>',"Agregar",()=>{
    if(needUser())return"Falta el usuario que registra.";const pid=$("sa_p").value,k=$("sa_x").value,m=$("sa_m").value.trim();if(!pid||!k)return"Elija paciente y examen.";if(m.length<4)return"Escriba el motivo.";
    if(solRecs(mes).some(r=>r.Paciente===pid&&r.Examen===k))return"Ese examen ya está en la solicitud del paciente.";
    addRec("sol","SL-",{Mes:mes,Programa:"hd",Paciente:pid,Examen:k,Origen:"Agregado manualmente",Motivo:m,Estado:"Pendiente"});reindex();render();toast("Examen agregado.");});}
function solTomada(pid,mes){if(needUser())return;const f=TODAY();let n=0;solRecs(mes).filter(r=>r.Paciente===pid&&r.Estado==="Pendiente").forEach(r=>{if(updRec("sol",r,{Estado:"Muestra tomada",FechaToma:f}))n++;});reindex();render();toast(n+" exámenes marcados con muestra tomada hoy.");}
function solExport(mes){ensureIdx();const[y,mm]=mes.split("-").map(Number);const R=solRecs(mes);let rows;
  if(R.length){const by={};R.forEach(r=>{(by[r.Paciente]=by[r.Paciente]||[]).push({k:r.Examen,why:r.Origen,r});});rows=Object.entries(by).map(([pid,ex])=>({p:IDX.pac.get(pid),ex})).filter(x=>x.p);}else rows=solPropuesta(mes);
  const keys=EXAMS.map(e=>e.k).filter(k=>rows.some(x=>x.ex.some(e=>e.k===k)));const firstDay=p=>{const d=turnoDias(p.Turno);for(let i=0;i<10;i++){const x=new Date(y,mm-1,1+i);if(d.includes(x.getDay()))return x;}return null;};
  exportSheets("Solicitud_laboratorio_HD_"+mes+".xlsx",[["Por paciente",rows,PID_COLS.map(c=>[c[0],x=>c[1](x.p)]).concat([["Turno",x=>x.p.Turno],["Silla",x=>x.p.Puesto],["Primera sesión del mes",x=>firstDay(x.p)]]).concat(keys.map(k=>[EX[k].l,x=>x.ex.some(e=>e.k===k)?"X":""]))],
    ["Detalle",rows.flatMap(x=>x.ex.map(e=>({p:x.p,e}))),PID_COLS.map(c=>[c[0],r=>c[1](r.p)]).concat([["Examen",r=>EX[r.e.k].l],["Origen",r=>r.e.why],["Estado",r=>r.e.r?(solResult(r.p.ID,r.e.k,mes)?"Con resultado":r.e.r.Estado):"Propuesta"],["Fecha de toma",r=>r.e.r?r.e.r.FechaToma:""],["Motivo",r=>r.e.r?r.e.r.Motivo:""]])],
    ["Resumen",keys.map(k=>({k,n:rows.filter(x=>x.ex.some(e=>e.k===k)).length})),[["Examen",r=>EX[r.k].l],["Pacientes",r=>r.n]]]]);}
function solExamsFor(p,mes){const R=solRecs(mes).filter(r=>r.Paciente===p.ID);if(R.length)return R.map(r=>r.Examen);const[y,mm]=mes.split("-").map(Number);return examsForMonth(p,y,mm).map(e=>e.k);}
/* carga de resultados de laboratorio limitada a lo solicitado en el mes */
function solCarga(){const mes=solMes("lab");const R=solRecs(mes);if(!R.length)return'<div class="panel empty">No hay solicitud generada para '+esc(mes)+'. Genérela en «Solicitud del mes».</div>';
  const pids=new Set(R.map(r=>r.Paciente));const ks=new Set(R.map(r=>r.Examen));if(ks.has("BUNpre")||ks.has("BUNpost")){ks.add("BUNpre");ks.add("BUNpost");}
  const ex=EXAMS.map(e=>e.k).filter(k=>ks.has(k)&&!["KtV","URR","TAS","EscalaCV"].includes(k));
  return'<div class="copyrow"><label class="f" style="min-width:160px">Solicitud del mes<input type="month" id="solmesL" value="'+mes+'"></label><span class="note">'+pids.size+' pacientes con solicitud · columnas: exámenes solicitados en el mes.</span></div>'+labCarga({pids,ex});}

/* ================= v0.2 · ruta del paciente en hemodiálisis (borrador por validar) ================= */
const RUTA_HD_DEF=[
 {k:"ing",t:"Ingreso a la unidad",v:["pac"],docs:"GSH-PT-001",m:["Verificar identidad con dos identificadores y diligenciar el consentimiento informado antes de la primera sesión.","Tener HBsAg, anti-HBc, anti-HBs, anti-VHC y VIH antes de iniciar; con HBsAg reactivo, máquina, sala y personal dedicados.","Definir el acceso vascular y, si es catéter, su plan hacia FAV o la exclusión con soporte.","Programar paquete de laboratorios de ingreso y valoración por nutrición, psicología y trabajo social.","Registrar el concepto inicial sobre trasplante."]},
 {k:"ses",t:"Sesión de hemodiálisis",v:["turno"],docs:"GSH-PR-002",m:["Confirmar paciente, prescripción y máquina antes de conectar.","Pesar antes y después; comparar el peso post con el peso seco y la tasa de UF con el límite de 13 mL/kg/h.","Higiene de manos en los cinco momentos y técnica aséptica en la conexión y desconexión del catéter.","Registrar todo evento de la sesión y marcar los que deben ir a seguridad del paciente.","Glucometría en pacientes con diabetes; hipoglucemia se maneja y se reporta."]},
 {k:"val",t:"Valoración mensual",v:["val"],docs:"",m:["Revisar GID, TA, eventos y asistencia de las últimas 8 sesiones antes de examinar.","Interpretar cada paraclínico contra la meta individual del paciente.","Revisar lo que hay que tener presente: estudios, vacunación y trasplante.","Dejar en la HC enfermedad actual, análisis y plan; ajustar peso seco si corresponde."]},
 {k:"lab",t:"Paraclínicos",v:["lab"],docs:"",m:["La solicitud del mes sale del calendario institucional y la valida laboratorio; toda corrección lleva motivo.","BUN pre y post en la misma sesión para calcular Kt/V.","HBsAg mensual en pacientes susceptibles.","Un resultado crítico se comunica de inmediato al médico de turno (por definir en el procedimiento de laboratorio)."]},
 {k:"vac",t:"Vacunación contra hepatitis B",v:["vac"],docs:"GSH-PT-001",m:["Susceptible: iniciar esquema de alta dosis sin esperar.","Anti-HBs 1 a 2 meses después de la última dosis; menor de 10, segunda serie completa.","No respondedor después de dos series: HBsAg mensual.","Respondedor: anti-HBs anual y refuerzo si baja de 10."]},
 {k:"acc",t:"Acceso vascular",v:["acc"],docs:"",m:["Cada catéter tiene un plan: FAV en curso o exclusión con soporte.","Signos de infección: hemocultivos antes del antibiótico y reporte a IAAS.","En el brazo de la FAV no se toma TA ni se puncionan venas.","Toda disfunción, recambio o retiro se registra como novedad del acceso."]},
 {k:"tx",t:"Trasplante",v:["tx"],docs:"",m:["Todo paciente tiene un concepto sobre trasplante documentado.","El candidato se remite a la IPS trasplantadora y se sigue la lista de estudios hasta completarla.","Los estudios a cargo de la IPS trasplantadora (HLA, anticuerpos) se registran con fecha cuando se conocen."]},
 {k:"ina",t:"Inasistencia y búsqueda activa",v:["alert"],docs:"",m:["Inasistencia sin aviso: contacto el mismo día y registro del contacto.","Notificar a trabajo social cuando se repite o no se logra contacto.","Un abandono solo se registra con desistimiento firmado o búsqueda activa documentada."]},
 {k:"seg",t:"Seguridad del paciente",v:[],docs:"UNO-P-SP-001",m:["Todo incidente o evento adverso se reporta; el reporte no busca culpables.","Los eventos adversos se analizan con el Protocolo de Londres y cierran con plan de mejora."]},
 {k:"egr",t:"Egreso de la unidad",v:[],docs:"",m:["Registrar el movimiento con fecha y soporte (epicrisis, acta, desistimiento).","Informar la novedad a la EPS y reflejarla en el reporte a la CAC."]}];
function rutaGet(){try{const P=window.PORTAL;if(P&&P.PX&&P.PX.book){const r=pxCfg("ruta_hd",null);if(Array.isArray(r)&&r.length)return r;}}catch(e){}return RUTA_HD_DEF;}
function rutaEstado(){try{const P=window.PORTAL;if(P&&P.PX&&P.PX.book)return pxCfg("ruta_hd_estado","Borrador por validar");}catch(e){}return"Borrador por validar";}
function rutaBanner(view){const s=rutaGet().find(x=>(x.v||[]).includes(view));if(!s||!ST.book)return"";const e=rutaEstado();
  return'<details class="panel hist" style="padding:6px 14px"><summary style="font-size:13.5px">Ruta del paciente · '+esc(s.t)+' <span class="tag '+(e==="Aprobada"?"cac":"inst")+'">'+esc(e.toLowerCase())+'</span></summary><ul style="margin:6px 0 0;padding-left:18px;font-size:13.5px">'+s.m.map(x=>'<li>'+esc(x)+'</li>').join("")+'</ul>'+(s.docs?'<p class="note" style="margin:4px 0 0">Documento: '+esc(s.docs)+'</p>':'')+'</details>';}

/* ================= v0.2 · acciones nuevas de Hemodiálisis (data-a) ================= */
function hdExtraAction(a,x,y,z,el){
  switch(a){
   case"vacf":ST.ui.vacf=x;render();return true;
   case"vacnew":dlgVac(x);return true;
   case"vacexp":vacExport();return true;
   case"txf":ST.ui.txf=x;render();return true;
   case"txsel":ST.ui.txp=x;render();return true;
   case"txsave":txSave(x);return true;
   case"txexp":txExport();return true;
   case"estrel":{if(needUser())return true;const e=ST.book.est.find(o=>o.ID===x);updRec("est",e,{Relevante:"No"});reindex();render();toast("Quitado de «tener presente». El estudio sigue en el historial.");return true;}
   case"solgen":solGenerar(x,false);return true;
   case"solnew":solGenerar(x,true);return true;
   case"soladd":dlgSolAdd(x);return true;
   case"solchip":dlgSolChip(x);return true;
   case"soltom":solTomada(x,y);return true;
   case"solexp":solExport(x||solMes());return true;
   case"pxgo":{const P=window.PORTAL;if(P&&P.PX&&P.PX.user){if(!pxCan(x)){toast("Su usuario no tiene acceso a ese módulo.");return true;}P.pxGo(x,y||null);}else toast("Ingrese al sistema de gestión para ir a ese módulo.");return true;}
  }
  return false;}
function hdExtraChange(t){if(t.id==="solmes"){ST.ui.solmes=t.value;render();return true;}if(t.id==="solmesL"){ST.ui.solmesL=t.value;render();return true;}return false;}

/* ================= v0.2 · datos ficticios adicionales (semilla propia para no alterar los anteriores) ================= */
function demoExtra(b,T){let seed=771205;const R=()=>{seed=(seed*1103515245+12345)%2147483648;return seed/2147483648;};const ri=(a,c)=>a+Math.floor(R()*(c-a+1)),pick=a=>a[Math.floor(R()*a.length)],ch=p=>R()<p;
  const ts=nowTs();const nid=(k,pre)=>{let mx=0;b[k].forEach(o=>{const m=/(\d+)$/.exec(o.ID||"");if(m)mx=Math.max(mx,+m[1]);});return pre+String(mx+1).padStart(6,"0");};
  const add=(k,pre,o)=>{const r=Object.assign({ID:nid(k,pre)},o,{Usuario:o.Usuario||"Enf. Paola R.",Registrado:ts});b[k].push(r);return r;};
  const yest=addDays(T,-1);
  /* UF de la máquina en las sesiones recientes */
  b.ses.forEach(s=>{if(s.Estado!=="Realizada"||num(s.PesoPre)==null||num(s.PesoPost)==null)return;const u=ufCalc(num(s.PesoPre),num(s.PesoPost),num(s.DuracionMin));if(!u)return;s.UFNeta=Math.round(u.kg*100)/100;s.UFR=u.ufr!=null?Math.round(u.ufr*10)/10:null;if(dayDiff(s.Fecha,T)<=75)s.UFMaquina=Math.max(0,Math.round(u.ml+ri(150,450)));});
  /* vacunación VHB coherente con los anti-HBs ficticios */
  const E1=CFG_DEF.vacEsq[0],E2=CFG_DEF.vacEsq[1];
  const serie=(p,first,esq,n,s)=>{esq.m.forEach((mo,i)=>{const d=addMonths(first,mo);if(d<=yest&&i<(n==null?99:n))add("vac","VC-",{Paciente:p.ID,Vacuna:"VHB",Esquema:esq.n,Serie:String(s||1),NumDosis:i+1,Fecha:d,Lote:"LOTE-DEMO-"+ri(100,999),Observacion:"",Usuario:"Enf. Maryury B."});});};
  let inm=false,nr2=0,anual=false,venc=false,pp=0;
  b.pac.forEach(p=>{if(!p._iv||!p._iv.length)return;const ing=p.IngresoUnidad||p.InicioTRR||T;const L=(p._lab.AntiHBs||[]);const last=L.length?num(L[L.length-1].Valor):null;const recent=dayDiff(p.InicioTRR||ing,T)<120;
    if(!recent&&last!=null&&last>=10&&!inm&&ch(.25)){inm=true;b.lab.push({ID:nid("lab","L-"),Paciente:p.ID,FechaToma:addDays(ing,-10),Examen:"AntiHBc",Valor:"Reactivo",Metodo:"",Usuario:"Laboratorio",Registrado:ts});p.VacunaVHB="No vacunado";return;}
    if(ch(.75))add("lab","L-",{Paciente:p.ID,FechaToma:addDays(ing,ri(-20,5)),Examen:"AntiHBc",Valor:"No reactivo",Metodo:"",Usuario:"Laboratorio"});
    if(recent){if(!venc){venc=true;serie(p,addMonths(T,-4),E1,1,1);return;}if(ch(.75))serie(p,addDays(p.InicioTRR||ing,ri(5,15)),E1,null,1);else p.VacunaVHB="No vacunado";return;}
    if(last!=null&&last>=10){serie(p,addMonths(T,anual?-ri(14,30):-30),pick([E1,E1,E2]),null,1);
      if(!anual){anual=true;b.lab=b.lab.filter(l=>!(l.Paciente===p.ID&&l.Examen==="AntiHBs"));b.lab.push({ID:nid("lab","L-"),Paciente:p.ID,FechaToma:addMonths(T,-14),Examen:"AntiHBs",Valor:ri(60,300),Metodo:"",Usuario:"Laboratorio",Registrado:ts});}return;}
    if(last!=null&&last<10){const r=R();if(r<0.35)serie(p,addMonths(T,-ri(14,24)),E1,null,1);else if(r<0.6&&nr2<2){nr2++;const f1=addMonths(T,-ri(26,30));serie(p,f1,E1,null,1);b.lab.push({ID:nid("lab","L-"),Paciente:p.ID,FechaToma:addMonths(f1,7),Examen:"AntiHBs",Valor:ri(0,8),Metodo:"",Usuario:"Laboratorio",Registrado:ts});serie(p,addMonths(f1,8),E1,null,2);b.lab.push({ID:nid("lab","L-"),Paciente:p.ID,FechaToma:addMonths(f1,15),Examen:"AntiHBs",Valor:ri(0,7),Metodo:"",Usuario:"Laboratorio",Registrado:ts});p.VHBNoRespondedor="SI";}
      else if(r<0.8&&pp<3){pp++;serie(p,addMonths(T,-ri(8,9)),E1,null,1);}else p.VacunaVHB="No vacunado";}});
  /* estudios, imágenes y procedimientos ficticios */
  const act=b.pac.filter(p=>p._iv&&p._iv.length&&activeAt(p,T));const E=[
   ["Imagen diagnóstica","Ecocardiograma","FEVI 42 %, hipertrofia concéntrica del VI, insuficiencia mitral leve. PSAP 38 mmHg.","Sí","Control con cardiología; cuidado con hipotensión intradiálisis",4],
   ["Imagen diagnóstica","Ecocardiograma","FEVI 60 %, sin alteraciones segmentarias. Derrame pericárdico mínimo.","Sí","Repetir ecocardiograma en 6 meses por derrame",-1],
   ["Imagen diagnóstica","Doppler de miembros superiores (mapeo vascular)","Vena cefálica izquierda de 3,1 mm permeable; arteria radial adecuada. Apto para FAV radiocefálica.","Sí","Remisión a cirugía vascular",3],
   ["Imagen diagnóstica","Radiografía de tórax","Cardiomegalia grado II, sin congestión.","No","",0],
   ["Procedimiento","Endoscopia digestiva alta","Gastritis crónica antral, H. pylori positivo.","Sí","Tratamiento de erradicación y control",2],
   ["Examen especializado","Holter de 24 horas","Extrasistolia ventricular frecuente (8 %), sin taquicardia sostenida.","Sí","Valoración por cardiología; potasio del baño",3],
   ["Concepto de especialista","Valoración por cardiología","Cardiopatía hipertensiva compensada; continuar carvedilol.","No","",0],
   ["Imagen diagnóstica","Ecografía renal y de vías urinarias","Riñones pequeños con aumento de ecogenicidad; quiste simple derecho de 2 cm.","No","",0]];
  E.forEach(([t,n,res,rel,seg,pc],i)=>{const p=act[(i*5+3)%act.length];const f=addDays(T,-ri(20,200));add("est","ES-",{Paciente:p.ID,Fecha:f,Tipo:t,Nombre:n,Resultado:res,Relevante:rel,Seguimiento:seg,ProximoControl:pc>0?addMonths(f,pc+2):pc<0?addDays(T,-6):null,Soporte:"HC · reporte escaneado (ficticio)",Usuario:"Dr. Nefrólogo (ficticio)"});});
  /* trasplante: avance ficticio de los que están en proceso */
  const IT=CFG_DEF.txItems;act.filter(p=>TX_EN_PROCESO.includes(p.TxEstado)).forEach(p=>{const lista=p.TxEstado==="En lista de espera";const nOk=lista?IT.length-ri(1,3):ri(4,12);IT.forEach((it,i)=>{if(i<nOk){add("txs","TX-",{Paciente:p.ID,Item:it,Estado:/odontol|urol/i.test(it)&&ch(.3)?"No aplica":"Realizado",Fecha:addDays(T,-ri(30,300)),Resultado:/ABO/.test(it)?pick(["O+","A+","B+","O-"]):/Ecocardiograma/.test(it)?"FEVI conservada":"",Usuario:"Coordinación renal"});}else if(i<nOk+2&&ch(.6))add("txs","TX-",{Paciente:p.ID,Item:it,Estado:"Solicitado",Fecha:addDays(T,-ri(5,40)),Resultado:"",Usuario:"Coordinación renal"});});});
  b.txs.sort((a,c)=>a.Fecha-c.Fecha);
  /* solicitud de laboratorio del mes en curso ya generada y en su mayoría tomada */
  ST.book=b;IDX.dirty=true;reindex();const mes=ym(T);let mx=0;solPropuesta(mes).forEach(({p,ex})=>{const s=p._ses.find(x=>ym(x.Fecha)===mes&&x.Estado==="Realizada");ex.forEach(e=>{mx++;const res=solResult(p.ID,e.k,mes);b.sol.push({ID:"SL-"+String(mx).padStart(6,"0"),Mes:mes,Programa:"hd",Paciente:p.ID,Examen:e.k,Origen:e.why,Motivo:"",Estado:res||s?"Muestra tomada":"Pendiente",FechaToma:res?res.FechaToma:(s?s.Fecha:null),Nota:"",Usuario:"Laboratorio",Registrado:ts});});});
  b.log.push({FechaHora:ts,Usuario:"Demostración",Accion:"GENERA",Hoja:"Vacunas, Estudios, TrasplanteSeguimiento, SolicitudesLab",Registro:"",Detalle:"Datos ficticios v0.2"});}
/* ================= arranque y eventos ================= */
function syncBar(){$("corte").value=iso(ST.corte);$("ps").value=iso(ST.ps);$("user").value=ST.user;$("feps").innerHTML=opt(epsList(),ST.eps,"Todas");}
function setBook(b,src){ST.book=b;ST.src=src;ST.dirty=false;ST.demo=false;ST.imp=null;ST.fin={key:null,data:null};ST.ui={};IDX.dirty=true;ST.corte=TODAY();ST.ps=cacStart(ST.corte);syncBar();bookInfo();render();}
function onFile(f){if(!f)return;const rd=new FileReader();rd.onload=ev=>{try{const wb=XLSX.read(new Uint8Array(ev.target.result),{type:"array",cellDates:false});
    if(ST.dirty&&ST.book&&!confirmLoss())return;
    if(isToolBook(wb)){setBook(parseToolBook(wb),f.name);toast("Libro cargado: "+ST.book.pac.length+" pacientes.");}
    else if(isDashboard(wb))dlgImport(wb,f.name);
    else toast("El archivo no tiene la hoja «Sesiones» del libro de hemodiálisis ni la hoja «2.PACIENTES» del Dashboard.");}catch(e){console.error(e);toast("No se pudo leer el archivo: "+e.message);}$("bookfile").value="";};rd.readAsArrayBuffer(f);}
function confirmLoss(){if(ST.ui.lossOk){ST.ui.lossOk=false;return true;}toast("Hay cambios sin descargar. Descargue el libro o vuelva a elegir el archivo para descartarlos.");ST.ui.lossOk=true;return false;}
$("bookfile").addEventListener("change",e=>onFile(e.target.files[0]));
$("bookdemo").addEventListener("click",()=>{if(ST.dirty&&ST.book&&!confirmLoss())return;loadDemo();});
$("booknew").addEventListener("click",()=>{if(ST.dirty&&ST.book&&!confirmLoss())return;setBook(newBook(),"Libro nuevo (vacío)");ST.view="pac";render();toast("Libro nuevo. Empiece por crear los pacientes.");});
$("bookexp").addEventListener("click",exportBook);
$("user").addEventListener("input",e=>{ST.user=e.target.value;try{localStorage.setItem("hd_usuario",ST.user);}catch(x){}});
$("corte").addEventListener("change",e=>{const d=pdate(e.target.value);if(d){ST.corte=d;if(ST.ps>d)ST.ps=cacStart(d);syncBar();bookInfo();render();}});
$("ps").addEventListener("change",e=>{const d=pdate(e.target.value);if(d&&d<=ST.corte){ST.ps=d;render();}else{toast("El inicio del periodo debe ser anterior al corte.");syncBar();}});
$("feps").addEventListener("change",e=>{ST.eps=e.target.value;render();});
$("nav").addEventListener("click",e=>{const b=e.target.closest("button[data-v]");if(!b)return;if(ST.view==="fin"&&b.dataset.v!=="fin")finLock();ST.view=b.dataset.v;render();});
window.addEventListener("beforeunload",e=>{if(ST.dirty){e.preventDefault();e.returnValue="";}});
const out=$("out");
function hdClick(e){const el=e.target.closest("[data-a]");if(!el||el.tagName==="INPUT"&&el.type==="checkbox")return;const[a,x,y,z]=el.dataset.a.split("|");
  if(hdExtraAction(a,x,y,z,el))return;
  switch(a){
   case"go2tx":ST.ui.txp=x;ST.ui.txf="all";ST.view="tx";render();window.scrollTo(0,0);break;
   case"vesqadd":{const V=vacEsquemas().slice();V.push({n:"Nuevo esquema "+(V.length+1),m:[0,1,6]});ST.book.cfgv.vacEsq=V;render();toast("Esquema agregado. Ajuste nombre y meses y guarde los parámetros.");break;}
   case"vesqdel":{const V=vacEsquemas().slice();if(V.length<2){toast("Debe quedar al menos un esquema.");return;}V.splice(+x,1);ST.book.cfgv.vacEsq=V;render();toast("Esquema quitado. Guarde los parámetros.");break;}
   case"demo":loadDemo();break;
   case"go":ST.view=x;render();window.scrollTo(0,0);break;
   case"pxn":if(typeof pxCompose==="function")pxCompose({tpl:+x,pid:y,det:z});break;
   case"tturno":ST.ui.tturno=x;ST.ui.evOpen=null;render();break;
   case"test":{const r=ST.ui.tdraft.rows[x];r.estado=r.estado===y?"":y;r.saved=false;if(y==="Realizada"&&r.estado){r.motivo="";}rerow(x);break;}
   case"tall":{let n=0;Object.values(ST.ui.tdraft.rows).forEach(r=>{if(!r.estado){r.estado="Realizada";r.saved=false;n++;}});render();toast(n+" pacientes marcados como realizada. Revise y guarde.");break;}
   case"tsave":tSave();break;
   case"tev":ST.ui.evOpen=ST.ui.evOpen===x?null:x;render();break;
   case"tevadd":{const t=$("ev_t").value;if(!t){toast("Elija el evento.");return;}const r=ST.ui.tdraft.rows[x];r.ev.push({Tipo:t,Severidad:$("ev_s").value,Conducta:$("ev_c").value.trim(),Resuelto:$("ev_r").value,Hemocultivo:t===ITS?($("ev_h").value||"Pendiente"):"",_sp:$("ev_sp").checked});r.saved=false;render();break;}
   case"tevdel":ST.ui.tdraft.rows[x].ev.splice(+y,1);render();break;
   case"pfe":ST.ui.pfe=x;render();break;
   case"psel":ST.sel.pac=x;ST.view="pac";render();break;
   case"pnew":ST.sel.pac="__new";ST.ui.pnew=null;render();break;
   case"psave":pacSave();break;
   case"preg":ST.ui.preg=x;render();break;
   case"pregsave":pacRegSave(x);break;
   case"anul":dlgAnular(x,y);break;
   case"evclose":{if(needUser())return;const ev=ST.book.evt.find(o=>o.ID===x);updRec("evt",ev,{Resuelto:"Sí",FechaCierre:TODAY()});reindex();render();toast("Evento cerrado.");break;}
   case"novclose":{const n=ST.book.nov.find(o=>o.ID===x);openDlg("Egreso de la hospitalización",'<label class="f">Fecha de egreso<input type="date" id="nv_f" value="'+iso(TODAY())+'"></label>',"Registrar egreso",()=>{if(needUser())return"Falta el usuario que registra.";const f=pdate($("nv_f").value);if(!f||f<n.Inicio)return"La fecha de egreso debe ser igual o posterior al ingreso ("+fd(n.Inicio)+").";updRec("nov",n,{Fin:f});reindex();render();toast("Egreso registrado.");});break;}
   case"ctc":dlgContacto(x,y);break;
   case"lsub":ST.ui.lsub=x;render();break;
   case"lsave":labSave();break;
   case"lcf":ST.ui.lcf=x;render();break;
   case"rsave":{if(needUser())return;const p=IDX.pac.get(x);const g=f=>{const el=document.querySelector('[data-r="'+x+'|'+f+'"]');return el?el.value.trim():"";};const ru=g("RutaAcceso"),so=g("SoporteRuta");if(RUTA_EXCL.includes(ru)&&so.length<5){toast("Para excluir del indicador hay que escribir el soporte.");return;}const ad=pdate(g("AccesoDesde"));if(ad&&ad>ST.corte){toast("La fecha del catéter no puede ser posterior al corte.");return;}const n=updRec("pac",p,{RutaAcceso:ru,SoporteRuta:so||null,FechaRuta:pdate(g("FechaRuta")),AccesoDesde:ad||p.AccesoDesde});render();toast(n?"Ruta de acceso actualizada.":"Sin cambios.");break;}
   case"sf":ST.ui.sf=x;render();break;
   case"isel":ST.sel.ind=x;render();break;
   case"corfreeze":corFreeze();break;
   case"cfgsave":cfgSave();break;
   case"turadd":{const T=turnosCfg().slice();T.push({n:"Nuevo turno "+(T.length+1),d:[1,3,5],j:"Noche"});ST.book.cfgv.turnos=T;render();toast("Turno agregado. Ajuste nombre y días, y guarde los parámetros.");break;}
   case"turdel":{const T=turnosCfg().slice();const t=T[+x];if(ST.book.pac.some(p=>p.Turno===t.n&&activeAt(p,ST.corte))){toast("Hay pacientes activos en «"+t.n+"»: cámbielos de turno primero.");return;}T.splice(+x,1);ST.book.cfgv.turnos=T;render();toast("Turno quitado. Guarde los parámetros.");break;}
   case"textra":dlgExtra();break;
   case"texpextra":dlgExpExtra();break;
   case"psub":ST.ui.psub=x;render();break;
   case"pmexp":expProxMes();break;
   case"vsave":valSave();break;
   case"vcopy":valCopy(x);break;
   case"vgo":ST.ui.vpid=x;ST.ui.vmes=ym(ST.corte);ST.view="val";render();window.scrollTo(0,0);break;
   case"accexp":accExport();break;
   case"acnew":dlgAccNov(x);break;
   case"semsub":ST.ui.semsub=x;render();break;
   case"calf":ST.ui.calf=x;render();break;
   case"ssub":ST.ui.ssub=x;render();break;
   case"spnew":dlgSP(null,x||null);break;
   case"spedit":dlgSP(x);break;
   case"iasave":{if(needUser())return;const ev=ST.book.evt.find(o=>o.ID===x);const g=f=>{const el=document.querySelector('[data-ia="'+x+'|'+f+'"]');return el?el.value.trim():"";};const ch={Hemocultivo:g("Hemocultivo"),Microorganismo:g("Microorganismo"),Resistencia:g("Resistencia"),Resuelto:g("Resuelto")};if(ch.Resuelto==="Sí"&&!ev.FechaCierre)ch.FechaCierre=TODAY();const n=updRec("evt",ev,ch);reindex();render();toast(n?(ch.Hemocultivo==="Positivo"&&ev.Tipo===ITS?"Bacteriemia confirmada: ya cuenta en el indicador dia_33.":"Infección actualizada."):"Sin cambios.");break;}
   case"atbnew":dlgAtb();break;
   case"atbend":{const a=ST.book.atb.find(o=>o.ID===x);openDlg("Terminar antimicrobiano",'<label class="f">Fecha de fin<input type="date" id="ae_f" value="'+iso(TODAY())+'"></label><label class="f">¿Ajustado a cultivo?<select id="ae_j">'+opt(["Sí","No","No aplica"],a.Ajustado==="Pendiente"?"":a.Ajustado)+'</select></label>',"Guardar",()=>{if(needUser())return"Falta el usuario que registra.";const f=pdate($("ae_f").value);if(!f||f<a.Inicio)return"La fecha de fin debe ser igual o posterior al inicio.";updRec("atb",a,{Fin:f,Ajustado:$("ae_j").value||a.Ajustado});reindex();render();toast("Tratamiento terminado.");});break;}
   case"audnew":dlgAud();break;
   case"fsub":ST.ui.fsub=x;render();break;
   case"dissave":disSave();break;
   case"mednew":dlgMed();break;
   case"medend":{const m=ST.book.med.find(o=>o.ID===x);openDlg("Suspender "+m.Medicamento,'<label class="f">Fecha de suspensión<input type="date" id="me_f" value="'+iso(TODAY())+'"></label><label class="f">Motivo<input type="text" id="me_m"></label>',"Suspender",()=>{if(needUser())return"Falta el usuario que registra.";const f=pdate($("me_f").value);if(!f)return"Fecha inválida.";updRec("med",m,{Fin:f,Nota:$("me_m").value.trim()});reindex();render();toast("Prescripción suspendida.");});break;}
   case"farexp":farExport();break;
   case"rep":repRun(x);break;
   case"bookexp2":exportBook();break;
   case"fcreate":finCreate();break;
   case"funlock":finUnlock();break;
   case"flock":finLock("Facturación bloqueada.");render();break;
   case"fsave":finSave();break;
   case"fclave":dlgClave();break;
   case"fadd":finRead();ST.fin.data.tarifas.push({eps:"",paquete:null,sesion:null,min:null,max:null,extra:"NO",desde:iso(TODAY())});finArm();render();break;
   case"fdel":finRead();ST.fin.data.tarifas.splice(+x,1);finArm();render();toast("Tarifa quitada. Guarde para que quede en el libro.");break;
  }}
out.addEventListener("click",hdClick);$("pxmain").addEventListener("click",hdClick);
function hdSubmit(e){if(e.target.id==="funl"){e.preventDefault();finUnlock();}}
out.addEventListener("submit",e=>{e.preventDefault();hdSubmit(e);});$("pxmain").addEventListener("submit",hdSubmit);
function hdChange(e){const t=e.target;if(hdExtraChange(t))return;
  if(t.id==="tdate"){ST.ui.tdate=t.value;ST.ui.evOpen=null;ST.ui.tdraft=null;render();return;}
  if(t.id==="ldate"){ST.ui.ldate=t.value;return;}
  if(t.id==="pmes"){ST.ui.pmes=t.value;render();return;}
  if(t.id==="vpid"){ST.ui.vpid=t.value;ST.ui.vdraft=null;render();return;}
  if(t.id==="vmes"){ST.ui.vmes=t.value;ST.ui.vdraft=null;render();return;}
  if(t.id==="tpid"){ST.ui.tpid=t.value;render();return;}
  if(t.id==="fames"){ST.ui.fames=t.value;render();return;}
  if(t.dataset&&t.dataset.vg){const[g,v]=t.dataset.vg.split("|");const D=ST.ui.vdraft;if(!D)return;const a=D.f[g]=(D.f[g]||[]).slice();const i=a.indexOf(v);if(t.checked&&i<0)a.push(v);if(!t.checked&&i>=0)a.splice(i,1);if(g==="sint"&&v==="Asintomático"&&t.checked)D.f.sint=["Asintomático"];if(g==="sint"&&v!=="Asintomático"&&t.checked)D.f.sint=D.f.sint.filter(x=>x!=="Asintomático");valRefresh();return;}
  if(t.dataset&&(t.dataset.v||t.dataset.vm)){vInput(t);return;}
  if(t.dataset&&t.dataset.re){tInput(t);rerow(t.dataset.t.split("|")[0]);return;}
  if(t.id==="fmes"){finRead();ST.ui.fmes=t.value;finArm();render();return;}
  if(t.dataset&&t.dataset.a&&t.dataset.a.startsWith("lex|")){const k=t.dataset.a.split("|")[1];const ex=(ST.ui.lex||LAB_GRID_DEF).slice();const i=ex.indexOf(k);if(t.checked&&i<0)ex.push(k);if(!t.checked&&i>=0)ex.splice(i,1);ST.ui.lex=EXAMS.map(e=>e.k).filter(k=>ex.includes(k));render();return;}
  tInput(t);}
out.addEventListener("change",hdChange);$("pxmain").addEventListener("change",hdChange);
function hdInput(e){const t=e.target;if(t.id==="pq"){ST.ui.pq=t.value;clearTimeout(ST.ui.pqt);ST.ui.pqt=setTimeout(()=>{render();const q=$("pq");if(q){q.focus();q.setSelectionRange(q.value.length,q.value.length);}},250);return;}if(t.dataset&&(t.dataset.v||t.dataset.vm)){vInput(t);return;}if(t.dataset&&t.dataset.l&&/BUN/.test(t.dataset.l)){labPreview(t.dataset.l.split("|")[1]);return;}tInput(t);if(t.dataset&&(t.dataset.ff||t.dataset.ft))finArm();}
out.addEventListener("input",hdInput);$("pxmain").addEventListener("input",hdInput);
function vInput(t){const D=ST.ui.vdraft;if(!D)return;if(t.dataset.v)D.f[t.dataset.v]=t.value;else D.metas[t.dataset.vm]=t.value;clearTimeout(ST.ui.vt);ST.ui.vt=setTimeout(valRefresh,350);}
function tInput(t){if(!t.dataset||!t.dataset.t||!ST.ui.tdraft)return;const[pid,f]=t.dataset.t.split("|");const r=ST.ui.tdraft.rows[pid];if(!r)return;r[f]=t.value;r.saved=false;if(["pp","pq","min","ufm"].includes(f)){const u=document.querySelector('[data-ufv="'+pid+'"]');if(u)u.innerHTML=ufView(IDX.pac.get(pid),r);}const tr=t.closest("tr");if(tr){tr.classList.remove("row-saved");tr.classList.add("row-dirty");}}
function rerow(pid){const tr=out.querySelector('tr[data-pid="'+pid+'"]');if(!tr){render();return;}const ev=tr.nextElementSibling&&tr.nextElementSibling.classList.contains("evrow")?tr.nextElementSibling:null;const tmp=document.createElement("tbody");tmp.innerHTML=tRow(IDX.pac.get(pid));if(ev)ev.remove();const nodes=[...tmp.children];tr.replaceWith(...nodes);
  const T=ST.ui.tdraft;const L=T.list;const done=L.filter(id=>T.rows[id].saved).length;const pend=L.filter(id=>!T.rows[id].estado).length;const n=$("tcount");if(n)n.textContent=L.length+" pacientes · "+done+" guardados · "+pend+" sin estado";}
document.addEventListener("keydown",e=>{if(e.key==="Escape"&&!$("dlg").hidden)closeDlg();});
window.HD={ST,loadDemo,render,reindex,calidad,alertas,evalInd,IND,INDM,ctxFor,conciliar,importDashboard,parseToolBook,buildWb,cacVals,calidadDe,gidStats,valCtx,valTexts,examsForMonth,labDue,ktvDaugirdas,expCAC,repRun,ufCalc,vacStatus,txState,tenerPresente,solPropuesta,solRecs,solResult,rutaGet};
syncBar();render();


